begin;
update public.authors set name_ka=coalesce(name_ka,'წმინდა იოანე დამასკელი'),title_ka=coalesce(title_ka,'დამასკელი; ეკლესიის მამა, ღვთისმეტყველი და წმინდა ხატების დამცველი'),position_ka=coalesce(position_ka,'მონაზონი და მღვდელი იერუსალიმთან მდებარე წმინდა საბას მონასტერში'),summary_ka=coalesce(summary_ka,'წმინდა იოანე დამასკელი (675–749) ეკლესიის ერთ-ერთი დიდი მამა და მართლმადიდებელი ღვთისმეტყველი იყო. დაიბადა დამასკოში, ქრისტიანულ ოჯახში. ღვთისმეტყველების, ფილოსოფიისა და წმინდა წერილის ღრმა ცოდნის გამო ეკლესიის ისტორიაში მნიშვნელოვანი ადგილი უკავია.'),biography_ka=coalesce(biography_ka,'იოანე დამასკელი დაახლოებით 675 ან 680 წელს დამასკოში, ომაიანთა სახალიფოს მმართველობის ქვეშ მყოფ ცნობილ ქრისტიანულ ოჯახში დაიბადა. მამამისი, სერგი მანსური, ხალიფის ფინანსურ უწყებაში პასუხისმგებელ თანამდებობას იკავებდა.

ბავშვობიდანვე იოანე რელიგიის, ფილოსოფიის, ლიტერატურისა და მუსიკის კარგ ცოდნას ეუფლებოდა. მამის გარდაცვალების შემდეგ, მისი ცხოვრების შესახებ გადმოცემის თანახმად, დამასკოში სახელმწიფო თანამდებობა მიიღო. მოგვიანებით კი ძალაუფლება და საერო ცხოვრება დატოვა და იერუსალიმთან მდებარე წმინდა საბას მონასტერში წავიდა.

იქ თავი ლოცვას, მარხვას, წმინდა წერილის შესწავლასა და საღვთისმეტყველო თხზულებების წერას მიუძღვნა. შემდგომ მღვდლად ეკურთხა და ეკლესიას ემსახურებოდა.

მის დროს ეკლესიაში წმინდა ხატების პატივისცემის შესახებ დიდი დავა მიმდინარეობდა. ხატმებრძოლეობის საწინააღმდეგო ცნობილ ნაწერებში წმინდა იოანე განმარტავდა, რომ ხატებზე გამოსახული პირების პატივისცემა ნივთიერების თაყვანისცემა არ არის: პატივი მიეგება იმ პირს, რომელსაც ხატი გამოსახავს.

სიცოცხლის მიწურულს იოანე წმინდა საბას მონასტერში დარჩა და დაახლოებით 749 წელს გარდაიცვალა. მისმა ნაწერებმა შემდგომ მნიშვნელოვანი გავლენა მოახდინა ნიკეის მეორე კრებაზე (787), რომელმაც მართლმადიდებლურ ეკლესიაში წმინდა ხატების პატივისცემა დაადასტურა.'),history_ka=coalesce(history_ka,''),contributions_ka=coalesce(contributions_ka,''),writings_intro_ka=coalesce(writings_intro_ka,''),life_dates_ka=coalesce(life_dates_ka,''),feast_ka=coalesce(feast_ka,''),icon_alt_ka=coalesce(icon_alt_ka,'წმინდა იოანე დამასკელი — მართლმადიდებლური ხატი'),icon_credit_ka=coalesce(icon_credit_ka,''),source_reference_ka=coalesce(source_reference_ka,''),birth_info_ka=coalesce(birth_info_ka,''),death_info_ka=coalesce(death_info_ka,'') where id='153e843f-d269-41ef-827d-4732d8fe047a';
update public.authors set name_ka=coalesce(name_ka,'წმინდა გრიგოლ ღვთისმეტყველი'),title_ka=coalesce(title_ka,'ღვთისმეტყველი'),position_ka=coalesce(position_ka,'კონსტანტინოპოლის მთავარეპისკოპოსი'),summary_ka=coalesce(summary_ka,'გრიგოლ ნაზიანზელი ბასილი დიდის ახლო მეგობარი იყო.'),biography_ka=coalesce(biography_ka,'გრიგოლ ნაზიანზელი ბასილი დიდის ახლო მეგობარი იყო. კონსტანტინოპოლში მისმა ქადაგებამ ნიკეის სარწმუნოების აღდგენის საქმეს შეუწყო ხელი. 381 წლის კრებას მცირე ხნით თავმჯდომარეობდა, შემდეგ კი განმარტოებით ცხოვრებას დაუბრუნდა. მის ქადაგებებში, წერილებსა და პოეზიაში წმინდა სამების შესახებ ზუსტი სწავლება ღრმა ლოცვით სულთან არის შერწყმული.'),history_ka=coalesce(history_ka,'აღმოსავლეთ რომის იმპერიაში არიანული სწავლების წინააღმდეგ ბრძოლა და კონსტანტინოპოლის 381 წლის კრება.'),contributions_ka=coalesce(contributions_ka,'განმარტა წმინდა სამების შესახებ გამოყენებული ტერმინები და დაიცვა ქრისტეს სრული ადამიანურობა, მათ შორის ადამიანური გონების არსებობა.'),writings_intro_ka=coalesce(writings_intro_ka,'ხუთი საღვთისმეტყველო სიტყვა (27–31); წერილები 101–102; საღვთისმეტყველო ლექსები.'),life_dates_ka=coalesce(life_dates_ka,'დაახლ. 329–389/390'),feast_ka=coalesce(feast_ka,'25 იანვარი'),icon_alt_ka=coalesce(icon_alt_ka,'წმინდა გრიგოლ ღვთისმეტყველი — მართლმადიდებლური ხატი'),icon_credit_ka=coalesce(icon_credit_ka,'უცნობი ხატმწერი · საჯარო საკუთრება. ასლის ზომა ვებგვერდისთვის შემცირებულია.'),source_reference_ka=coalesce(source_reference_ka,'https://www.oca.org/saints/id/lives/100298'),birth_info_ka=coalesce(birth_info_ka,''),death_info_ka=coalesce(death_info_ka,'') where id='2d7f8b57-2a33-40ad-876e-baf7c4496a34';
