update public.prayers set title_ka=coalesce(title_ka,'ღვთისმშობელო ქალწულო, გიხაროდენ'),reference_ka=coalesce(reference_ka,'მოკითხვა მთავარანგელოსისა მიერ ყოვლადწმიდისა ღვთისმშობელისა. ქართული ტექსტი: https://orthodoxy.ge/lotsvani/dilis.htm'),topic_ka=coalesce(topic_ka,'ღვთისმშობელი'),text_ka=coalesce(text_ka,'ღვთისმშობელო ქალწულო, გიხაროდენ, მიმადლებულო მარიამ, უფალი შენთანა, კურთხეულ ხარ შენ დედათა შორის და კურთხეულ არს ნაყოფი მუცლისა შენისა, რამეთუ მაცხოვარი გვიშევ სულთა ჩვენთა.') where id='10000000-0000-4000-8000-000000000004';
update public.prayers set title_ka=coalesce(title_ka,'უფლის ლოცვა — მამაო ჩვენო'),reference_ka=coalesce(reference_ka,'უფლის ლოცვა. ქართული ტექსტი: https://orthodoxy.ge/lotsvani/dilis.htm'),topic_ka=coalesce(topic_ka,'ძირითადი ლოცვები'),text_ka=coalesce(text_ka,'მამაო ჩვენო, რომელი ხარ ცათა შინა, წმიდა იყავნ სახელი შენი, მოვედინ სუფევა შენი, იყავნ ნება შენი, ვითარცა ცათა შინა, ეგრეცა ქვეყანასა ზედა, პური ჩვენი არსობისა მომეც ჩვენ დღეს, და მომიტევენ ჩვენ თანანადებნი ჩვენნი, ვითარცა ჩვენ მივუტევებთ თანამდებთა მათ ჩვენთა და ნუ შემიყვანებ ჩვენ განსაცდელსა, არამედ მიხსენ ჩვენ ბოროტისაგან, ამინ.') where id='10000000-0000-4000-8000-000000000005';
