update public.doctrines set title_ka=coalesce(title_ka,'ნიკეის მეორე მსოფლიო კრება'),subtitle_ka=coalesce(subtitle_ka,'ხატისთვის მიგებული პატივი პირველსახეზე გადადის; თაყვანისცემა მხოლოდ ღმერთს ეკუთვნის.'),body_ka=coalesce(body_ka,'ხატისთვის მიგებული პატივი პირველსახეზე გადადის; თაყვანისცემა მხოლოდ ღმერთს ეკუთვნის.'),reference_ka=coalesce(reference_ka,''),bible_references_ka=coalesce(bible_references_ka,''),father_references_ka=coalesce(father_references_ka,''),council_references_ka=coalesce(council_references_ka,''),icon_alt_ka=coalesce(icon_alt_ka,''),icon_credit_ka=coalesce(icon_credit_ka,'') where id='b60819e2-ea99-4ec6-80d3-e473451633dd';
update public.doctrines set title_ka=coalesce(title_ka,'წმინდა სამება'),subtitle_ka=coalesce(subtitle_ka,'ღმერთი არსებით ერთია და პირებით სამია: მამა, ძე და სულიწმიდა. ამ სამ პირს ერთი განუყოფელი ღმრთაებრივი არსება აქვს; ისინი დიდებით თანასწორნი არიან, ღმრთეება საერთო აქვთ და მარადიულად ერთი სამება ღმერთია. ისინი დაუსაბამონი არიან; ამასთან, სამი ღმერთი კი არ არიან, არამედ ერთი ღმერთი. მამა უშობელია, ძე მამისაგან მარადიულად იშვება, ხოლო სულიწმიდა მამისაგან მარადიულად გამოდის. ეს არის ღმერთი, რომელსაც აღმოსავლური, რუმის მართლმადიდებელი ეკლესია თაყვანს სცემს და თავის სარწმუნოებაში აღიარებს.

წმინდა სამების შესახებ ეკლესიის აღსარება არიოზის მცდარი სწავლების წინააღმდეგ განმტკიცდა. არიოზი უარყოფდა, რომ ძე — იესო ქრისტე — ჭეშმარიტად ღმერთია.

ნიკეის პირველმა მსოფლიო კრებამ (325) გამოაცხადა, რომ ძე მამის „ერთარსია“ (homoousios), ხოლო კონსტანტინოპოლში გამართულმა მეორე მსოფლიო კრებამ (381) სულიწმიდის ღმრთეების აღსარება შეავსო.'),body_ka=coalesce(body_ka,'ღმერთი არსებით ერთია და პირებით სამია: მამა, ძე და სულიწმიდა. ამ სამ პირს ერთი განუყოფელი ღმრთაებრივი არსება აქვს; ისინი დიდებით თანასწორნი არიან, ღმრთეება საერთო აქვთ და მარადიულად ერთი სამება ღმერთია. ისინი დაუსაბამონი არიან; ამასთან, სამი ღმერთი კი არ არიან, არამედ ერთი ღმერთი. მამა უშობელია, ძე მამისაგან მარადიულად იშვება, ხოლო სულიწმიდა მამისაგან მარადიულად გამოდის. ეს არის ღმერთი, რომელსაც აღმოსავლური, რუმის მართლმადიდებელი ეკლესია თაყვანს სცემს და თავის სარწმუნოებაში აღიარებს.

წმინდა სამების შესახებ ეკლესიის აღსარება არიოზის მცდარი სწავლების წინააღმდეგ განმტკიცდა. არიოზი უარყოფდა, რომ ძე — იესო ქრისტე — ჭეშმარიტად ღმერთია.

ნიკეის პირველმა მსოფლიო კრებამ (325) გამოაცხადა, რომ ძე მამის „ერთარსია“ (homoousios), ხოლო კონსტანტინოპოლში გამართულმა მეორე მსოფლიო კრებამ (381) სულიწმიდის ღმრთეების აღსარება შეავსო.'),reference_ka=coalesce(reference_ka,'https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/the-holy-trinity/the-doctrine-of-the-holy-trinity'),bible_references_ka=coalesce(bible_references_ka,'მათე 28:19'),father_references_ka=coalesce(father_references_ka,''),council_references_ka=coalesce(council_references_ka,''),icon_alt_ka=coalesce(icon_alt_ka,''),icon_credit_ka=coalesce(icon_credit_ka,'') where id='c07ee532-800d-41a0-8c59-1ec1357ebd04';
