update public.doctrines set title_ka=coalesce(title_ka,'ეფესოს მსოფლიო კრება'),subtitle_ka=coalesce(subtitle_ka,'ქრისტე ერთი პირია; მარიამი არის ღვთისმშობელი — თეოტოკოსი.'),body_ka=coalesce(body_ka,'ქრისტე ერთი პირია; მარიამი არის ღვთისმშობელი — თეოტოკოსი.'),reference_ka=coalesce(reference_ka,''),bible_references_ka=coalesce(bible_references_ka,''),father_references_ka=coalesce(father_references_ka,''),council_references_ka=coalesce(council_references_ka,''),icon_alt_ka=coalesce(icon_alt_ka,''),icon_credit_ka=coalesce(icon_credit_ka,'') where id='dbf56a3a-f0f3-490d-87af-b556448c154d';
update public.doctrines set title_ka=coalesce(title_ka,'წმინდანთა თანაზიარება'),subtitle_ka=coalesce(subtitle_ka,''),body_ka=coalesce(body_ka,''),reference_ka=coalesce(reference_ka,''),bible_references_ka=coalesce(bible_references_ka,''),father_references_ka=coalesce(father_references_ka,''),council_references_ka=coalesce(council_references_ka,''),icon_alt_ka=coalesce(icon_alt_ka,''),icon_credit_ka=coalesce(icon_credit_ka,'') where id='f57b2aa4-f83c-43a0-85cc-6445d5e3224e';
update public.bible_explanations set title_ka=coalesce(title_ka,'წმინდა იოანე ოქროპირის განმარტება'),body_ka=coalesce(body_ka,'იოანე 1:1
„დასაბამში იყო მიწა“, ან ადამიანზე — „დასაბამში იყო ადამიანი“ — რომ თქმულიყო, იმაზეც კი ვერ წარმოვიდგენდით ვერაფერს იმაზე აღმატებულს, რაც უკვე ვიცით. რადგან სიტყვები „მიწა“ და „ადამიანი“, როგორც წინასწარ განსაზღვრული სახელები, რამდენიც უნდა ითქვას მათ შესახებ, გონებას არ აძლევს საშუალებას, მათზე იმაზე მეტი წარმოიდგინოს, რაც უკვე იცის. ასევეა „სიტყვაც“.

იოანეს ჩვენთან თავისი აზრით რომ ესაუბრა და საკუთარი სიტყვა გადმოეცა, უეჭველად საჭირო იქნებოდა მის ოჯახზე, სამშობლოსა და აღზრდაზე საუბარი. მაგრამ რადგან კაცობრიობას თვითონ კი არ ელაპარაკება, არამედ ღმერთი მეტყველებს მისი — იოანეს — მეშვეობით, შეიძლება ვიფიქროთ, რომ ამის გამოკვლევა უსარგებლო და ყურადღების გამფანტავია. თუმცა ეს არა მხოლოდ უსარგებლო არ არის, არამედ ძალიან საჭიროცაა. როდესაც გაიგებ, ვინ იყო, საიდან იყო, ვინ იყვნენ მისი მშობლები და როგორი პიროვნება იყო, შემდეგ კი მის ხმასა და მთელ ამ ზეციურ სიბრძნეს მოისმენ, ცხადად მიხვდები, რომ ეს სწავლება მისი საკუთარი კი არ არის, არამედ იმ ღმრთაებრივი ძალისაა, რომელმაც მისი სული აამოძრავა.

რომელი ქვეყნიდან იყო იგი? სახელოვანი ქვეყნის მკვიდრი არ ყოფილა; ღარიბი სოფლის მკვიდრი იყო, იმ მხარიდან, რომელსაც უმნიშვნელოდ მიიჩნევდნენ და საიდანაც კარგს არაფერს ელოდნენ.

რადგან სჯულის მოძღვრები გალილეაზე ცუდად ლაპარაკობენ და ამბობენ: „გამოიკვლიე და ნახე, რომ გალილეიდან წინასწარმეტყველი არ აღდგება“ (იოანე 7:52). „ჭეშმარიტი ისრაელიტელიც“ მის შესახებ ამბობს: „განა შეიძლება ნაზარეთიდან რაიმე კარგი გამოვიდეს?“

მიუხედავად იმისა, რომ ამ მხარის მკვიდრი იყო, იქაც კი რომელიმე გამორჩეული ადგილიდან კი არ იყო, არამედ ისეთი ადგილიდან, რომლის სახელიც არ იცოდნენ.

იგი აქედან იყო, მამამისი კი ღარიბი მეთევზე იყო — იმდენად ღარიბი, რომ შვილებიც იმავე ხელობაში ჩააბა. ყველამ იცით, რომ არც ერთ მუშაკს არ სურს, შვილი საკუთარი ხელობის გასაგრძელებლად გაზარდოს, თუ მძიმე სიღარიბე არ აიძულებს, განსაკუთრებით მაშინ, როდესაც ხელობა დაბალ და უმნიშვნელო საქმედ ითვლება.

მეთევზეებზე ღარიბი, უფრო დაბალი სოციალური მდგომარეობის მქონე და უსწავლელი არავინ იყო. თუმცა მათ შორისაც ზოგი უფრო დიდი იყო, ზოგი კი — უფრო მცირე; და იქაც ჩვენი მოციქული უფრო დაბალ საფეხურზე იდგა, რადგან ზღვაში კი არ თევზაობდა, არამედ პატარა ტბაზე ატარებდა დროს. როდესაც იმ ტბის ნაპირას მამასთან და თავის ძმა იაკობთან ერთად დახეულ ბადეებს კერავდა — რაც თავისთავად უკიდურესი სიღარიბის ნიშანი იყო — სწორედ მაშინ მოუხმო მას ქრისტემ.'),reference_ka=coalesce(reference_ka,'იოანე ოქროპირი — ქადაგებები იოანეს სახარებაზე (არსებულ ჩანაწერში ზუსტი ქადაგებისა და პარაგრაფის ნომერი მითითებული არ არის).'),review_note_ka=coalesce(review_note_ka,'ეს არის ადმინისტრატორის მიერ შეყვანილი სორანიული ტექსტის ქართული თარგმანი; წყაროს ზუსტი ადგილი საეკლესიო რედაქტორის გადამოწმებას საჭიროებს.') where id='43e0b9f0-9eaa-491d-ac7c-532190c629da';
update public.bible_editions set title_ka=coalesce(title_ka,'სორანიული — ღია სტანდარტული თარგმანი'),description_ka=coalesce(description_ka,'სორანიული გამოცემა 66 წიგნს შეიცავს. მართლმადიდებლური კანონის დამატებითი წიგნები ამ თარგმანში შესული არ არის.') where id='ckb_bib';
update public.bible_editions set title_ka=coalesce(title_ka,'ინგლისური — განახლებული მსოფლიო ინგლისური ბიბლია'),description_ka=coalesce(description_ka,'ინგლისური გამოცემა შეიცავს მეორეკანონიკურ და დამატებით წიგნებს. წიგნების თანმიმდევრობა და ფსალმუნთა ნუმერაცია ამ თარგმანს შეესაბამება.') where id='eng_webu';
update public.sources set title_ka=coalesce(title_ka,'წმინდა გარდამოცემა'),content_ka=coalesce(content_ka,'წმინდა გარდამოცემა არის ეკლესიაში გადმოცემული ცხოვრება და სარწმუნოება. წმინდა წერილს მასში უმთავრესი ადგილი უკავია. დროებითი ადამიანური ჩვეულებები მარადიული სამოციქულო სარწმუნოებისგან უნდა განვასხვაოთ.'),publisher_ka=coalesce(publisher_ka,'ამერიკის მართლმადიდებელი ეკლესია') where id='00000000-0000-4000-8000-000000000001';
update public.sources set title_ka=coalesce(title_ka,'ბიბლია მართლმადიდებლურ სარწმუნოებაში'),content_ka=coalesce(content_ka,'მართლმადიდებლობაში ბიბლია საღმრთო სწავლების მთავარი წერილობითი მოწმობაა. ეკლესია მას სულიწმიდით შთაგონებულად იღებს და მის წიგნებს იესო ქრისტესთან კავშირში კითხულობს.'),publisher_ka=coalesce(publisher_ka,'მართლმადიდებელი ეკლესია') where id='00000000-0000-4000-8000-000000000002';
update public.sources set title_ka=coalesce(title_ka,'წმინდა წერილის განმარტება'),content_ka=coalesce(content_ka,'წმინდა წერილის მართლმადიდებლური განმარტება ეკლესიის ცოცხალ გარდამოცემასა და ღვთისმსახურებაში შეკრებილი მორწმუნე საზოგადოების ცხოვრებას ეკუთვნის. სულიწმიდა წარმართავს ქრისტეს შესახებ ბიბლიური მოწმობის ამგვარ გაგებას.'),publisher_ka=coalesce(publisher_ka,'ამერიკის მართლმადიდებელი ეკლესია') where id='00000000-0000-4000-8000-000000000003';
update public.sources set title_ka=coalesce(title_ka,'სარწმუნოება'),content_ka=coalesce(content_ka,'ქრისტიანული სარწმუნოება ღმერთის ნდობა და მისდამი ერთგულებაა. სარწმუნოების სიმბოლო ეკლესიის წიაღში პიროვნულ აღსარებას გამოხატავს. სარწმუნოება განუყოფელია იმედისგან, სიყვარულისგან და სულიწმიდის მიერ წარმართული ცხოვრებისგან.'),publisher_ka=coalesce(publisher_ka,'ამერიკის მართლმადიდებელი ეკლესია') where id='00000000-0000-4000-8000-000000000004';
