update public.content_blocks set text_ka=coalesce(text_ka,'ჩვენი სარწმუნოება და საეკლესიო გადმოცემა') where key='home.about';
update public.content_blocks set text_ka=coalesce(text_ka,'ჩვენი წყაროებია წმინდა წერილი, ეკლესიის მამები და სანდო მართლმადიდებლური გამოცემები. სარედაქციო თარგმანები სათანადოდ არის აღნიშნული. პირადი სულიერი ხელმძღვანელობისთვის მართლმადიდებელ მღვდელს მიმართეთ.') where key='home.aboutPolicy';
update public.content_blocks set text_ka=coalesce(text_ka,'ეს საიტი ეკუთვნის და წარმოადგენს აღმოსავლეთის მართლმადიდებლურ ქრისტიანულ ტრადიციას — უძველეს ეკლესიას, რომელიც ჩვენმა უფალმა იესო ქრისტემ დააფუძნა და რომელიც საუკუნეების განმავლობაში მართლმადიდებელი ეკლესიის სარწმუნოებაში, ღვთისმსახურებაში, წმინდა გადმოცემასა და სამოციქულო მემკვიდრეობაშია დაცული.

სიტყვას „მართლმადიდებელი“ სხვა ქრისტიანული ტრადიციებიც იყენებენ, მათ შორის ორიენტალური, ანუ ძველაღმოსავლური მართლმადიდებელი ეკლესიები, როგორიცაა კოპტური, სირიული და სომხური ეკლესიები. მიუხედავად იმისა, რომ ამ ეკლესიებს უძველესი ქრისტიანული ფესვები და ადრეული ქრისტიანული გადმოცემის მრავალი ელემენტი აქვთ, ისინი ცალკე საეკლესიო ერთობას წარმოადგენენ და აღმოსავლეთის მართლმადიდებელი ეკლესიის შემადგენლობაში არ შედიან.

ამიტომ ჩვენი საეკლესიო ტრადიციის მკაფიოდ და ზუსტად დასასახელებლად ვიყენებთ ტერმინებს „აღმოსავლეთის მართლმადიდებლობა“ და „რუმის მართლმადიდებლობა“. ეს სახელწოდებები ჩვენს საეკლესიო იდენტობას განასხვავებს სხვა ქრისტიანული ტრადიციებისგან, რომლებიც ასევე იყენებენ სახელს „მართლმადიდებელი“.
ჩვენ ვეკუთვნით აღმოსავლეთის მართლმადიდებელ ეკლესიას, რომლის კანონიკური ცხოვრება მის ავტოკეფალურ და ავტონომიურ ეკლესიებში ვლინდება, მათ შორის კონსტანტინოპოლის, ალექსანდრიის, ანტიოქიისა და იერუსალიმის საპატრიარქოებში, აგრეთვე რუსეთის, საქართველოს, საბერძნეთის, სერბეთის, რუმინეთის, ბულგარეთისა და სხვა ეკლესიებში.

ჩვენი მიზანია აღმოსავლეთის მართლმადიდებელი ეკლესიის ჭეშმარიტი სარწმუნოების გაზიარება წმინდა წერილზე, წმინდა გადმოცემაზე, მსოფლიო საეკლესიო კრებებზე, საღმრთო ლიტურგიასა და ეკლესიის წმინდა მამათა ნაშრომებსა და სწავლებაზე დაყრდნობით.

ჩვენი საფუძველი ქრისტეა. ჩვენი სარწმუნოება მართლმადიდებლურია. ჩვენი ტრადიცია აღმოსავლეთის მართლმადიდებლობაა.') where key='home.aboutText';
