insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.saintsDescription','discover','The lives, teachings, and works of Orthodox saints.','ژیان، فێرکاری و بەرهەمەکانی پایەپیرۆزانی ئۆرتۆدۆکس.','Jiyan, hînkirin û berhemên pîrozên Ortodoks.','მართლმადიდებელ წმინდანთა ცხოვრება, სწავლებები და ნაშრომები.',true) on conflict(key) do nothing;
