insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.readingDescription','discover','Read the writings of the Holy Fathers and Orthodox spiritual literature.','نووسینەکانی باوکانی کڵێسا و ئەدەبیاتی ڕۆحیی ئۆرتۆدۆکس بخوێنەوە.','Nivîsên Bavên Dêrê û edebiyata giyanî ya Ortodoks bixwîne.','წაიკითხეთ წმინდა მამათა ნაშრომები და მართლმადიდებლური სასულიერო ლიტერატურა.',true) on conflict(key) do nothing;
insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.history','discover','Orthodox History','مێژووی ئۆرتۆدۆکس','Dîroka Ortodoksiyê','მართლმადიდებლობის ისტორია',true) on conflict(key) do nothing;
insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.historyDescription','discover','Discover the history and heritage of the Orthodox Church.','مێژوو و میراتی کڵێسای ئۆرتۆدۆکس بناسە.','Dîrok û mîrateya Dêra Ortodoks nas bike.','გაეცანით მართლმადიდებელი ეკლესიის ისტორიასა და მემკვიდრეობას.',true) on conflict(key) do nothing;
insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.councils','discover','Councils','ئەنجومەنەکان','Civînên Dêrê','საეკლესიო კრებები',true) on conflict(key) do nothing;
insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.councilsDescription','discover','Explore the Seven Ecumenical Councils and other important synods.','حەوت ئەنجومەنی گشتی و ئەنجومەنە گرنگەکانی دیکە بناسە.','Heft Civînên Ekumenîk û civînên din ên girîng nas bike.','გაეცანით შვიდ მსოფლიო კრებასა და სხვა მნიშვნელოვან საეკლესიო კრებებს.',true) on conflict(key) do nothing;
