insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.theologyDescription','discover','Study Orthodox doctrine and theology.','عەقیدە و خوداناسیی ئۆرتۆدۆکس بخوێنە.','Doktrîn û teolojiya Ortodoks bixwîne.','შეისწავლეთ მართლმადიდებლური მოძღვრება და ღვთისმეტყველება.',true) on conflict(key) do nothing;
