insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.prayersDescription','discover','Discover traditional Orthodox prayers and liturgical texts.','نوێژە نەریتییەکان و دەقە پەرستنییەکانی ئۆرتۆدۆکس بناسە.','Duayên kevneşopî û nivîsên lîturjîk ên Ortodoks nas bike.','გაეცანით ტრადიციულ მართლმადიდებლურ ლოცვებსა და საღვთისმსახურო ტექსტებს.',true) on conflict(key) do nothing;
insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.empty','discover','No categories match your search.','هیچ بەشێک لەگەڵ گەڕانەکەت ناگونجێت.','Tu beş li lêgerîna te nayê.','თქვენი ძიების შესაბამისი განყოფილება ვერ მოიძებნა.',true) on conflict(key) do nothing;
insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.readingEmpty','discover','No writings have been published yet.','هێشتا هیچ نووسینێک بڵاو نەکراوەتەوە.','Hêj tu nivîs nehatiye weşandin.','ნაშრომები ჯერ არ გამოქვეყნებულა.',true) on conflict(key) do nothing;
insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.historyEmpty','discover','No historical articles have been published yet.','هێشتا هیچ وتارێکی مێژوویی بڵاو نەکراوەتەوە.','Hêj tu gotara dîrokî nehatiye weşandin.','ისტორიული სტატიები ჯერ არ გამოქვეყნებულა.',true) on conflict(key) do nothing;
