insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.imageSources','discover','Historical image sources','سەرچاوەی وێنە مێژووییەکان','Çavkaniyên wêneyên dîrokî','ისტორიული გამოსახულებების წყაროები',true) on conflict(key) do nothing;
insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.iconSources','discover','Traditional icons: source credits are available on each saint’s profile.','ئایکۆنە نەریتییەکان: سەرچاوەکان لە پڕۆفایلی هەر پایەپیرۆزێکدا هەن.','Îkonên kevneşopî: çavkanî li profîla her pîrozî hene.','ტრადიციული ხატების წყაროები მითითებულია თითოეული წმინდანის გვერდზე.',true) on conflict(key) do nothing;
insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.manuscriptSource','discover','Jaharis Byzantine Lectionary, about 1100 · The Metropolitan Museum of Art · Public domain','دەستنووسی بیزەنتیی جاهاریس، نزیکەی ١١٠٠ · مۆزەخانەی مێترۆپۆلیتن · موڵکی گشتی','Lectionarya Bîzansî ya Jaharis, nêzî 1100 · Muzeya Metropolitan · Milkê giştî','იაჰარისის ბიზანტიური სახარება, დაახლოებით 1100 წელი · მეტროპოლიტენის მუზეუმი · საჯარო საკუთრება',true) on conflict(key) do nothing;
insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('discover.loadError','discover','This collection could not be loaded. Please try again.','ئەم کۆمەڵەیە بار نەبوو. تکایە دووبارە هەوڵ بدەوە.','Ev berhevok nehat barkirin. Ji kerema xwe dîsa biceribîne.','კრებულის ჩატვირთვა ვერ მოხერხდა. გთხოვთ, სცადოთ ხელახლა.',true) on conflict(key) do nothing;
insert into public.content_blocks (key,section,text_en,text_ckb,text_kmr,text_ka,published) values('general.navDiscover','general','Discover','گەڕان و دۆزینەوە','Bikole','აღმოაჩინე',true) on conflict(key) do nothing;
insert into public.bible_editions (id,title_en,title_ckb,title_kmr,title_ka,description_en,description_ckb,description_kmr,description_ka,sort_order,published) values('ka_ogb','Old Georgian New Testament','پەیمانی نوێ بە گورجیی کۆن','Peymana Nû bi Gurcîya kevn','ახალი აღთქმა — ძველი ქართული ტექსტი','Historical Old Georgian text, 27 New Testament books. Digital source: pumenis/random-access-ogb, MIT license.','دەقی مێژوویی گورجیی کۆن؛ ٢٧ کتێبی پەیمانی نوێ.','Nivîsa dîrokî ya Gurcîya kevn; 27 pirtûkên Peymana Nû.','ისტორიული ძველი ქართული ტექსტი. შეიცავს ახალი აღთქმის 27 წიგნს; თანამედროვე ქართული თარგმანი არ არის. ციფრული წყარო: pumenis/random-access-ogb, MIT ლიცენზია.',2,true) on conflict(id) do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'peter','Saint Peter the Apostle','پایەپیرۆز پەترۆسی نێردراو','წმინდა პეტრე მოციქული','June 29','٢٩ی حوزەیران','29 ივნისი','Peter was a Galilean fisherman and the brother of Andrew.','پەترۆس ماسیگرێکی جەلیلی و برای ئەندراوس بوو.','პეტრე გალილეველი მეთევზე და ანდრიას ძმა იყო.','Peter was a Galilean fisherman and the brother of Andrew. He followed Christ as one of the Twelve Apostles and preached after Pentecost. Church tradition remembers his martyrdom in Rome under Nero.','پەترۆس ماسیگرێکی جەلیلی و برای ئەندراوس بوو. وەک یەکێک لە دوازدە نێردراوەکە شوێنی مەسیح کەوت و دوای پەنجاکۆست مژدەی ڕاگەیاند. نەریتی کڵێسا شەهیدبوونی ئەو لە ڕۆما لە سەردەمی نیرۆدا یاد دەکاتەوە.','პეტრე გალილეველი მეთევზე და ანდრიას ძმა იყო. იგი ქრისტეს თორმეტ მოციქულს შორის იყო და სულთმოფენობის შემდეგ სახარებას ქადაგებდა. საეკლესიო გადმოცემა მის მოწამებრივ აღსასრულს რომში, ნერონის მმართველობის ხანაში იხსენიებს.','Apostle','نێردراو','მოციქული','/icons/saints/peter.webp','https://www.oca.org/saints/lives/2026/06/29/101841-the-holy-glorious-and-all-praised-leader-of-the-apostles-peter','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/06/29/101841-the-holy-glorious-and-all-praised-leader-of-the-apostles-peter','Orthodox Church in America, Lives of the Saints — Saint Peter the Apostle',array['Simon Peter','Cephas','პეტრე']::text[],'Saint Peter the Apostle — traditional Orthodox icon','წმინდა პეტრე მოციქული — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა პეტრე მოციქული
https://www.oca.org/saints/lives/2026/06/29/101841-the-holy-glorious-and-all-praised-leader-of-the-apostles-peter','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/06/29/101841-the-holy-glorious-and-all-praised-leader-of-the-apostles-peter',true,100,'saints-expansion-2026:peter' where not exists(select 1 from public.authors where slug='peter' or legacy_key='saints-expansion-2026:peter' or lower(name_en)=lower('Saint Peter the Apostle')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'paul','Saint Paul the Apostle','پایەپیرۆز پۆڵسی نێردراو','წმინდა პავლე მოციქული','June 29','٢٩ی حوزەیران','29 ივნისი','Paul, originally called Saul, came from Tarsus.','پۆڵس، کە سەرەتا شائول ناوی بوو، خەڵکی تەرسوس بوو.','პავლე, რომელსაც თავდაპირველად სავლე ერქვა, ტარსოსიდან იყო.','Paul, originally called Saul, came from Tarsus. After encountering Christ on the road to Damascus, he received baptism and became a missionary among the nations. His epistles form an important part of the New Testament.','پۆڵس، کە سەرەتا شائول ناوی بوو، خەڵکی تەرسوس بوو. دوای دیداری مەسیح لە ڕێگای دیمەشق، مەعمودیەتی وەرگرت و بوو بە مژدەبەر لەنێو گەلاندا. نامەکانی بەشێکی گرنگی پەیمانی نوێ پێکدەهێنن.','პავლე, რომელსაც თავდაპირველად სავლე ერქვა, ტარსოსიდან იყო. დამასკოს გზაზე ქრისტეს გამოცხადების შემდეგ იგი მოინათლა და წარმართთა შორის სახარების მქადაგებელი გახდა. მისი ეპისტოლეები ახალი აღთქმის მნიშვნელოვან ნაწილს შეადგენს.','Apostle','نێردراو','მოციქული','/icons/saints/paul.webp','https://www.oca.org/saints/lives/2026/06/29/101842-the-holy-glorious-and-all-praised-leader-of-the-apostles-paul','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/06/29/101842-the-holy-glorious-and-all-praised-leader-of-the-apostles-paul','Orthodox Church in America, Lives of the Saints — Saint Paul the Apostle',array['Saul of Tarsus','Apostle to the Gentiles','პავლე']::text[],'Saint Paul the Apostle — traditional Orthodox icon','წმინდა პავლე მოციქული — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა პავლე მოციქული
https://www.oca.org/saints/lives/2026/06/29/101842-the-holy-glorious-and-all-praised-leader-of-the-apostles-paul','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/06/29/101842-the-holy-glorious-and-all-praised-leader-of-the-apostles-paul',true,101,'saints-expansion-2026:paul' where not exists(select 1 from public.authors where slug='paul' or legacy_key='saints-expansion-2026:paul' or lower(name_en)=lower('Saint Paul the Apostle')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'andrew','Saint Andrew the First-Called','پایەپیرۆز ئەندراوسی یەکەم بانگکراو','წმინდა ანდრია პირველწოდებული','November 30','٣٠ی تشرینی دووەم','30 ნოემბერი','Andrew was a fisherman from Bethsaida and the brother of Peter.','ئەندراوس ماسیگرێکی بێت‌سەیدا و برای پەترۆس بوو.','ანდრია ბეთსაიდელი მეთევზე და პეტრეს ძმა იყო.','Andrew was a fisherman from Bethsaida and the brother of Peter. He was among the first disciples to follow Christ and brought his brother to Him. Orthodox tradition associates his apostolic preaching with the lands around the Black Sea and his martyrdom with Patras.','ئەندراوس ماسیگرێکی بێت‌سەیدا و برای پەترۆس بوو. لە یەکەم قوتابییەکانی مەسیح بوو و براکەی بۆ لای ئەو هێنا. نەریتی ئۆرتۆدۆکس مژدەبەریی ئەو بە ناوچەکانی دەریای ڕەش و شەهیدبوونی بە شاری پاتراسەوە دەبەستێتەوە.','ანდრია ბეთსაიდელი მეთევზე და პეტრეს ძმა იყო. იგი ქრისტეს პირველ მოწაფეთა შორის იყო და თავისი ძმაც მასთან მიიყვანა. მართლმადიდებლური გადმოცემა მის ქადაგებას შავი ზღვისპირეთს უკავშირებს, მოწამებრივ აღსასრულს კი — პატრას.','Apostle','نێردراو','მოციქული','/icons/saints/andrew.webp','https://www.oca.org/saints/lives/2026/11/30/103450-apostle-andrew-the-holy-and-all-praised-first-called','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/11/30/103450-apostle-andrew-the-holy-and-all-praised-first-called','Orthodox Church in America, Lives of the Saints — Saint Andrew the First-Called',array['Andrew Protokletos','First Called','ანდრია პირველწოდებული']::text[],'Saint Andrew the First-Called — traditional Orthodox icon','წმინდა ანდრია პირველწოდებული — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა ანდრია პირველწოდებული
https://www.oca.org/saints/lives/2026/11/30/103450-apostle-andrew-the-holy-and-all-praised-first-called','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/11/30/103450-apostle-andrew-the-holy-and-all-praised-first-called',true,102,'saints-expansion-2026:andrew' where not exists(select 1 from public.authors where slug='andrew' or legacy_key='saints-expansion-2026:andrew' or lower(name_en)=lower('Saint Andrew the First-Called')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'john-theologian','Saint John the Theologian','پایەپیرۆز یۆحەنای باوەڕناس','წმინდა იოანე ღვთისმეტყველი','September 26','٢٦ی ئەیلوول','26 სექტემბერი','John, the son of Zebedee and brother of James, was one of the Twelve Apostles.','یۆحەنا، کوڕی زەبدی و برای یاقوب، یەکێک لە دوازدە نێردراوەکە بوو.','იოანე, ზებედეს ძე და იაკობის ძმა, თორმეტ მოციქულთაგანი იყო.','John, the son of Zebedee and brother of James, was one of the Twelve Apostles. He witnessed the Transfiguration and stood beside the Mother of God at the Cross. The Church venerates him as an evangelist and theologian and remembers his ministry in Ephesus.','یۆحەنا، کوڕی زەبدی و برای یاقوب، یەکێک لە دوازدە نێردراوەکە بوو. شایەتی گۆڕانی شێوەی مەسیح بوو و لەبەر خاچەکە لەتەنیشت دایکی خودا ڕاوەستا. کڵێسا وەک مژدەنووس و باوەڕناس ڕێزی لێ دەگرێت و خزمەتی لە ئەفەسۆس یاد دەکاتەوە.','იოანე, ზებედეს ძე და იაკობის ძმა, თორმეტ მოციქულთაგანი იყო. იგი ქრისტეს ფერისცვალების მოწმე გახდა და ჯვართან ღვთისმშობლის გვერდით იდგა. ეკლესია მას მახარებლად და ღვთისმეტყველად პატივს მიაგებს და ეფესოში მის მსახურებას იხსენებს.','Apostle','نێردراو','მოციქული','/icons/saints/john-theologian.webp','https://www.oca.org/saints/lives/2026/09/26/102731-repose-of-the-holy-apostle-and-evangelist-john-the-theologian','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/09/26/102731-repose-of-the-holy-apostle-and-evangelist-john-the-theologian','Orthodox Church in America, Lives of the Saints — Saint John the Theologian',array['John the Evangelist','John son of Zebedee','იოანე მახარებელი']::text[],'Saint John the Theologian — traditional Orthodox icon','წმინდა იოანე ღვთისმეტყველი — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა იოანე ღვთისმეტყველი
https://www.oca.org/saints/lives/2026/09/26/102731-repose-of-the-holy-apostle-and-evangelist-john-the-theologian','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/09/26/102731-repose-of-the-holy-apostle-and-evangelist-john-the-theologian',true,103,'saints-expansion-2026:john-theologian' where not exists(select 1 from public.authors where slug='john-theologian' or legacy_key='saints-expansion-2026:john-theologian' or lower(name_en)=lower('Saint John the Theologian')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'james-zebedee','Saint James the Son of Zebedee','پایەپیرۆز یاقوبی کوڕی زەبدی','წმინდა იაკობ ზებედეს ძე','April 30','٣٠ی نیسان','30 აპრილი','James, the son of Zebedee, was the brother of John the Theologian and one of the Twelve Apostles.','یاقوبی کوڕی زەبدی برای یۆحەنای باوەڕناس و یەکێک لە دوازدە نێردراوەکە بوو.','იაკობ ზებედეს ძე იოანე ღვთისმეტყველის ძმა და თორმეტ მოციქულთაგანი იყო.','James, the son of Zebedee, was the brother of John the Theologian and one of the Twelve Apostles. With Peter and John he witnessed the Transfiguration of Christ. Acts records that Herod had him put to death by the sword in Jerusalem.','یاقوبی کوڕی زەبدی برای یۆحەنای باوەڕناس و یەکێک لە دوازدە نێردراوەکە بوو. لەگەڵ پەترۆس و یۆحەنا شایەتی گۆڕانی شێوەی مەسیح بوو. پەڕتووکی کردار دەگێڕێتەوە کە هێرۆد لە ئۆرشەلیم بە شمشێر لەناوی برد.','იაკობ ზებედეს ძე იოანე ღვთისმეტყველის ძმა და თორმეტ მოციქულთაგანი იყო. პეტრესა და იოანესთან ერთად იგი ქრისტეს ფერისცვალებას დაესწრო. მოციქულთა საქმეების თანახმად, ჰეროდემ იგი იერუსალიმში მახვილით მოაკვლევინა.','Apostle','نێردراو','მოციქული','/icons/saints/james-zebedee.webp','https://www.oca.org/saints/lives/2026/04/30/101248-apostle-james-the-brother-of-saint-john-the-theologian','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/04/30/101248-apostle-james-the-brother-of-saint-john-the-theologian','Orthodox Church in America, Lives of the Saints — Saint James the Son of Zebedee',array['James the Greater','James son of Zebedee','იაკობ ზებედეს ძე']::text[],'Saint James the Son of Zebedee — traditional Orthodox icon','წმინდა იაკობ ზებედეს ძე — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა იაკობ ზებედეს ძე
https://www.oca.org/saints/lives/2026/04/30/101248-apostle-james-the-brother-of-saint-john-the-theologian','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/04/30/101248-apostle-james-the-brother-of-saint-john-the-theologian',true,104,'saints-expansion-2026:james-zebedee' where not exists(select 1 from public.authors where slug='james-zebedee' or legacy_key='saints-expansion-2026:james-zebedee' or lower(name_en)=lower('Saint James the Son of Zebedee')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'thomas','Saint Thomas the Apostle','پایەپیرۆز تۆمای نێردراو','წმინდა თომა მოციქული','October 6','٦ی تشرینی یەکەم','6 ოქტომბერი','Thomas was one of the Twelve Apostles.','تۆما یەکێک لە دوازدە نێردراوەکە بوو.','თომა თორმეტ მოციქულთაგანი იყო.','Thomas was one of the Twelve Apostles. The Gospel of John records his encounter with the risen Christ and his confession of faith. Church tradition remembers him as a preacher of the Gospel in India and as a martyr.','تۆما یەکێک لە دوازدە نێردراوەکە بوو. مژدەی یۆحەنا دیداری ئەو لەگەڵ مەسیحی هەستاوە و دانپێدانانی باوەڕەکەی دەگێڕێتەوە. نەریتی کڵێسا وەک مژدەبەر لە هیندستان و شەهید یاد دەکاتەوە.','თომა თორმეტ მოციქულთაგანი იყო. იოანეს სახარება აღწერს მის შეხვედრას მკვდრეთით აღდგომილ ქრისტესთან და მის მიერ რწმენის აღიარებას. საეკლესიო გადმოცემა მას ინდოეთში სახარების მქადაგებლად და მოწამედ იხსენიებს.','Apostle','نێردراو','მოციქული','/icons/saints/thomas.webp','https://www.oca.org/saints/lives/2026/10/06/102885-holy-glorious-apostle-thomas','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/10/06/102885-holy-glorious-apostle-thomas','Orthodox Church in America, Lives of the Saints — Saint Thomas the Apostle',array['Didymus','Apostle Thomas','თომა']::text[],'Saint Thomas the Apostle — traditional Orthodox icon','წმინდა თომა მოციქული — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა თომა მოციქული
https://www.oca.org/saints/lives/2026/10/06/102885-holy-glorious-apostle-thomas','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/10/06/102885-holy-glorious-apostle-thomas',true,105,'saints-expansion-2026:thomas' where not exists(select 1 from public.authors where slug='thomas' or legacy_key='saints-expansion-2026:thomas' or lower(name_en)=lower('Saint Thomas the Apostle')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'matthew','Saint Matthew the Evangelist','پایەپیرۆز مەتای مژدەنووس','წმინდა მათე მახარებელი','November 16','١٦ی تشرینی دووەم','16 ნოემბერი','Matthew, also called Levi, was a tax collector in Capernaum before following Christ.','مەتا، کە بە لێڤیش ناسراوە، پێش شوێنکەوتنی مەسیح باجگری کەفەرناحوم بوو.','მათე, რომელსაც ლევიც ეწოდებოდა, ქრისტეს მოწოდებამდე კაპერნაუმში მებაჟედ მსახურობდა.','Matthew, also called Levi, was a tax collector in Capernaum before following Christ. He became one of the Twelve Apostles. The Church receives him as the author of the Gospel that bears his name.','مەتا، کە بە لێڤیش ناسراوە، پێش شوێنکەوتنی مەسیح باجگری کەفەرناحوم بوو. بوو بە یەکێک لە دوازدە نێردراوەکە. کڵێسا وەک نووسەری ئەو مژدەیەی بە ناوی ئەوەوەیە دەیناسێت.','მათე, რომელსაც ლევიც ეწოდებოდა, ქრისტეს მოწოდებამდე კაპერნაუმში მებაჟედ მსახურობდა. იგი თორმეტ მოციქულთაგანი გახდა. ეკლესია მას მისი სახელით ცნობილი სახარების ავტორად აღიარებს.','Apostle','نێردراو','მოციქული','/icons/saints/matthew.webp','https://www.oca.org/saints/lives/2026/11/16/103313-apostle-and-evangelist-matthew','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/11/16/103313-apostle-and-evangelist-matthew','Orthodox Church in America, Lives of the Saints — Saint Matthew the Evangelist',array['Levi','Matthew the Apostle','მათე']::text[],'Saint Matthew the Evangelist — traditional Orthodox icon','წმინდა მათე მახარებელი — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა მათე მახარებელი
https://www.oca.org/saints/lives/2026/11/16/103313-apostle-and-evangelist-matthew','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/11/16/103313-apostle-and-evangelist-matthew',true,106,'saints-expansion-2026:matthew' where not exists(select 1 from public.authors where slug='matthew' or legacy_key='saints-expansion-2026:matthew' or lower(name_en)=lower('Saint Matthew the Evangelist')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'mark','Saint Mark the Evangelist','پایەپیرۆز مەرقۆسی مژدەنووس','წმინდა მარკოზ მახარებელი','April 25','٢٥ی نیسان','25 აპრილი','Mark, also known as John Mark, was a companion of the Apostles Peter, Paul, and Barnabas.','مەرقۆس، کە بە یۆحەنا مەرقۆسیش ناسراوە، هاوڕێی نێردراوان پەترۆس و پۆڵس و بەرناباس بوو.','მარკოზი, რომელსაც იოანე მარკოზსაც უწოდებდნენ, პეტრე, პავლე და ბარნაბა მოციქულების თანამოღვაწე იყო.','Mark, also known as John Mark, was a companion of the Apostles Peter, Paul, and Barnabas. He wrote the Gospel that bears his name. Orthodox tradition remembers his preaching and martyrdom in Alexandria.','مەرقۆس، کە بە یۆحەنا مەرقۆسیش ناسراوە، هاوڕێی نێردراوان پەترۆس و پۆڵس و بەرناباس بوو. ئەو مژدەیەی نووسی کە بە ناوی ئەوەوەیە. نەریتی ئۆرتۆدۆکس مژدەبەری و شەهیدبوونی لە ئەسکەندەریە یاد دەکاتەوە.','მარკოზი, რომელსაც იოანე მარკოზსაც უწოდებდნენ, პეტრე, პავლე და ბარნაბა მოციქულების თანამოღვაწე იყო. მან დაწერა მისი სახელით ცნობილი სახარება. მართლმადიდებლური გადმოცემა ალექსანდრიაში მის ქადაგებასა და მოწამებრივ აღსასრულს იხსენიებს.','Apostle','نێردراو','მოციქული','/icons/saints/mark.webp','https://www.oca.org/saints/lives/2026/04/25/101204-apostle-and-evangelist-mark','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/04/25/101204-apostle-and-evangelist-mark','Orthodox Church in America, Lives of the Saints — Saint Mark the Evangelist',array['John Mark','Mark the Apostle','მარკოზი']::text[],'Saint Mark the Evangelist — traditional Orthodox icon','წმინდა მარკოზ მახარებელი — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა მარკოზ მახარებელი
https://www.oca.org/saints/lives/2026/04/25/101204-apostle-and-evangelist-mark','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/04/25/101204-apostle-and-evangelist-mark',true,107,'saints-expansion-2026:mark' where not exists(select 1 from public.authors where slug='mark' or legacy_key='saints-expansion-2026:mark' or lower(name_en)=lower('Saint Mark the Evangelist')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'luke','Saint Luke the Evangelist','پایەپیرۆز لۆقای مژدەنووس','წმინდა ლუკა მახარებელი','October 18','١٨ی تشرینی یەکەم','18 ოქტომბერი','Luke was a physician and a companion of the Apostle Paul.','لۆقا پزیشک و هاوڕێی پۆڵسی نێردراو بوو.','ლუკა ექიმი და პავლე მოციქულის თანამოღვაწე იყო.','Luke was a physician and a companion of the Apostle Paul. The Church receives him as the author of the Gospel of Luke and the Acts of the Apostles. His writings bear witness to the life of Christ and the spread of the apostolic preaching.','لۆقا پزیشک و هاوڕێی پۆڵسی نێردراو بوو. کڵێسا وەک نووسەری مژدەی لۆقا و کردارەکانی نێردراوان دەیناسێت. نووسینەکانی شایەتی ژیانی مەسیح و بڵاوبوونەوەی مژدەی نێردراوان دەدەن.','ლუკა ექიმი და პავლე მოციქულის თანამოღვაწე იყო. ეკლესია მას ლუკას სახარებისა და მოციქულთა საქმეების ავტორად აღიარებს. მისი ნაწერები ქრისტეს ცხოვრებისა და სამოციქულო ქადაგების გავრცელების შესახებ მოგვითხრობს.','Apostle','نێردراو','მოციქული','/icons/saints/luke.webp','https://www.oca.org/saints/lives/2026/10/18/102993-apostle-and-evangelist-luke','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/10/18/102993-apostle-and-evangelist-luke','Orthodox Church in America, Lives of the Saints — Saint Luke the Evangelist',array['Luke the Apostle','ლუკა']::text[],'Saint Luke the Evangelist — traditional Orthodox icon','წმინდა ლუკა მახარებელი — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა ლუკა მახარებელი
https://www.oca.org/saints/lives/2026/10/18/102993-apostle-and-evangelist-luke','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/10/18/102993-apostle-and-evangelist-luke',true,108,'saints-expansion-2026:luke' where not exists(select 1 from public.authors where slug='luke' or legacy_key='saints-expansion-2026:luke' or lower(name_en)=lower('Saint Luke the Evangelist')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'philip','Saint Philip the Apostle','پایەپیرۆز فیلیپۆسی نێردراو','წმინდა ფილიპე მოციქული','November 14','١٤ی تشرینی دووەم','14 ნოემბერი','Philip came from Bethsaida in Galilee and was called by Christ to follow Him.','فیلیپۆس خەڵکی بێت‌سەیدای جەلیل بوو و مەسیح بانگی کرد بۆ شوێنکەوتنی.','ფილიპე გალილეის ბეთსაიდიდან იყო და ქრისტემ მას თავის მიმდევრად მოუწოდა.','Philip came from Bethsaida in Galilee and was called by Christ to follow Him. The Gospel of John records that he brought Nathanael to the Lord. Church tradition remembers his preaching in Asia Minor and his martyrdom at Hierapolis.','فیلیپۆس خەڵکی بێت‌سەیدای جەلیل بوو و مەسیح بانگی کرد بۆ شوێنکەوتنی. مژدەی یۆحەنا دەگێڕێتەوە کە نەسەنائیلی بۆ لای پەروەردگار هێنا. نەریتی کڵێسا مژدەبەریی ئەو لە ئاسیای بچووک و شەهیدبوونی لە هیراپۆلیس یاد دەکاتەوە.','ფილიპე გალილეის ბეთსაიდიდან იყო და ქრისტემ მას თავის მიმდევრად მოუწოდა. იოანეს სახარების თანახმად, მან ნათანაელი უფალთან მიიყვანა. საეკლესიო გადმოცემა მცირე აზიაში მის ქადაგებასა და იერაპოლისში მის მოწამებრივ აღსასრულს იხსენიებს.','Apostle','نێردراو','მოციქული','/icons/saints/philip.webp','https://www.oca.org/saints/lives/2026/11/14/103299-holy-all-praised-apostle-philip','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/11/14/103299-holy-all-praised-apostle-philip','Orthodox Church in America, Lives of the Saints — Saint Philip the Apostle',array['Philip of Bethsaida','ფილიპე']::text[],'Saint Philip the Apostle — traditional Orthodox icon','წმინდა ფილიპე მოციქული — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა ფილიპე მოციქული
https://www.oca.org/saints/lives/2026/11/14/103299-holy-all-praised-apostle-philip','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/11/14/103299-holy-all-praised-apostle-philip',true,109,'saints-expansion-2026:philip' where not exists(select 1 from public.authors where slug='philip' or legacy_key='saints-expansion-2026:philip' or lower(name_en)=lower('Saint Philip the Apostle')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'bartholomew','Saint Bartholomew the Apostle','پایەپیرۆز بەرتۆلماوسی نێردراو','წმინდა ბართლომე მოციქული','June 11','١١ی حوزەیران','11 ივნისი','Bartholomew was one of the Twelve Apostles.','بەرتۆلماوس یەکێک لە دوازدە نێردراوەکە بوو.','ბართლომე თორმეტ მოციქულთაგანი იყო.','Bartholomew was one of the Twelve Apostles. Church tradition associates his missionary journeys with the Apostle Philip in Syria and Asia Minor, and later with Armenia. He is venerated as a martyr for Christ.','بەرتۆلماوس یەکێک لە دوازدە نێردراوەکە بوو. نەریتی کڵێسا گەشتە مژدەبەرییەکانی لەگەڵ فیلیپۆسی نێردراو لە سووریا و ئاسیای بچووک، و دواتر لە ئەرمەنستان یاد دەکاتەوە. وەک شەهیدێک بۆ مەسیح ڕێزی لێ دەگیرێت.','ბართლომე თორმეტ მოციქულთაგანი იყო. საეკლესიო გადმოცემა მის სამისიონერო გზას ფილიპე მოციქულთან ერთად სირიასა და მცირე აზიას, მოგვიანებით კი სომხეთს უკავშირებს. იგი ქრისტესთვის მოწამედ იდიდება.','Apostle','نێردراو','მოციქული','/icons/saints/bartholomew.webp','https://www.oca.org/saints/lives/2026/06/11/101690-apostle-bartholomew-of-the-twelve','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/06/11/101690-apostle-bartholomew-of-the-twelve','Orthodox Church in America, Lives of the Saints — Saint Bartholomew the Apostle',array['Nathanael','Bartholomaios','ბართლომე']::text[],'Saint Bartholomew the Apostle — traditional Orthodox icon','წმინდა ბართლომე მოციქული — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა ბართლომე მოციქული
https://www.oca.org/saints/lives/2026/06/11/101690-apostle-bartholomew-of-the-twelve','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/06/11/101690-apostle-bartholomew-of-the-twelve',true,110,'saints-expansion-2026:bartholomew' where not exists(select 1 from public.authors where slug='bartholomew' or legacy_key='saints-expansion-2026:bartholomew' or lower(name_en)=lower('Saint Bartholomew the Apostle')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'james-alphaeus','Saint James the Son of Alphaeus','پایەپیرۆز یاقوبی کوڕی حەلفی','წმინდა იაკობ ალფეს ძე','October 9','٩ی تشرینی یەکەم','9 ოქტომბერი','James, the son of Alphaeus, was one of the Twelve Apostles and a witness to Christ’s teaching.','یاقوبی کوڕی حەلفی یەکێک لە دوازدە نێردراوەکە و شایەتی فێرکاریی مەسیح بوو.','იაკობ ალფეს ძე თორმეტ მოციქულთაგანი და ქრისტეს სწავლების მოწმე იყო.','James, the son of Alphaeus, was one of the Twelve Apostles and a witness to Christ’s teaching. Church tradition remembers his preaching after Pentecost and his martyrdom in Egypt. He is distinct from James the son of Zebedee and James the Brother of the Lord.','یاقوبی کوڕی حەلفی یەکێک لە دوازدە نێردراوەکە و شایەتی فێرکاریی مەسیح بوو. نەریتی کڵێسا مژدەبەریی ئەو دوای پەنجاکۆست و شەهیدبوونی لە میسر یاد دەکاتەوە. ئەو جیاوازە لە یاقوبی کوڕی زەبدی و یاقوبی برای پەروەردگار.','იაკობ ალფეს ძე თორმეტ მოციქულთაგანი და ქრისტეს სწავლების მოწმე იყო. საეკლესიო გადმოცემა სულთმოფენობის შემდეგ მის ქადაგებასა და ეგვიპტეში მის მოწამებრივ აღსასრულს იხსენიებს. იგი განსხვავდება იაკობ ზებედეს ძისა და იაკობ უფლის ძმისაგან.','Apostle','نێردراو','მოციქული','/icons/saints/james-alphaeus.webp','https://www.oca.org/saints/lives/2026/10/09/102916-apostle-james-son-of-alphaeus','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/10/09/102916-apostle-james-son-of-alphaeus','Orthodox Church in America, Lives of the Saints — Saint James the Son of Alphaeus',array['James Alphaeus','James the Less','იაკობ ალფესი']::text[],'Saint James the Son of Alphaeus — traditional Orthodox icon','წმინდა იაკობ ალფეს ძე — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა იაკობ ალფეს ძე
https://www.oca.org/saints/lives/2026/10/09/102916-apostle-james-son-of-alphaeus','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/10/09/102916-apostle-james-son-of-alphaeus',true,111,'saints-expansion-2026:james-alphaeus' where not exists(select 1 from public.authors where slug='james-alphaeus' or legacy_key='saints-expansion-2026:james-alphaeus' or lower(name_en)=lower('Saint James the Son of Alphaeus')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'simon-zealot','Saint Simon the Zealot','پایەپیرۆز شیمۆنی دڵگەرم','წმინდა სიმონ კანანელი','May 10','١٠ی ئایار','10 მაისი','Simon the Zealot was one of the Twelve Apostles and came from Cana in Galilee.','شیمۆنی دڵگەرم یەکێک لە دوازدە نێردراوەکە و خەڵکی قانای جەلیل بوو.','სიმონ კანანელი თორმეტ მოციქულთაგანი და გალილეის კანას მკვიდრი იყო.','Simon the Zealot was one of the Twelve Apostles and came from Cana in Galilee. After Pentecost he preached the Gospel. The Church venerates him as a martyr and distinguishes him from the Apostle Simon Peter.','شیمۆنی دڵگەرم یەکێک لە دوازدە نێردراوەکە و خەڵکی قانای جەلیل بوو. دوای پەنجاکۆست مژدەی ڕاگەیاند. کڵێسا وەک شەهید ڕێزی لێ دەگرێت و لە شیمۆن پەترۆسی نێردراو جیای دەکاتەوە.','სიმონ კანანელი თორმეტ მოციქულთაგანი და გალილეის კანას მკვიდრი იყო. სულთმოფენობის შემდეგ იგი სახარებას ქადაგებდა. ეკლესია მას მოწამედ პატივს მიაგებს და სიმონ-პეტრე მოციქულისაგან განასხვავებს.','Apostle','نێردراو','მოციქული','/icons/saints/simon-zealot.webp','https://www.oca.org/saints/lives/2026/05/10/101337-apostle-simon-the-zealot','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/05/10/101337-apostle-simon-the-zealot','Orthodox Church in America, Lives of the Saints — Saint Simon the Zealot',array['Simon Kananaios','Simon the Canaanite','Simon Zelotes','სიმონ მოშურნე']::text[],'Saint Simon the Zealot — traditional Orthodox icon','წმინდა სიმონ კანანელი — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა სიმონ კანანელი
https://www.oca.org/saints/lives/2026/05/10/101337-apostle-simon-the-zealot','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/05/10/101337-apostle-simon-the-zealot',true,112,'saints-expansion-2026:simon-zealot' where not exists(select 1 from public.authors where slug='simon-zealot' or legacy_key='saints-expansion-2026:simon-zealot' or lower(name_en)=lower('Saint Simon the Zealot')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,position_en,position_ckb,position_ka,icon_url,icon_source,icon_credit,source_url,source_reference,aliases,icon_alt,icon_alt_ka,source_reference_ka,icon_credit_ka,published,sort_order,legacy_key) select 'jude','Saint Jude the Apostle','پایەپیرۆز یەهودای نێردراو','წმინდა იუდა მოციქული','June 19','١٩ی حوزەیران','19 ივნისი','Jude was one of the Twelve Apostles and is also known in the Church as the brother of James.','یەهودا یەکێک لە دوازدە نێردراوەکە بوو و لە کڵێسادا بە برای یاقوبیش ناسراوە.','იუდა თორმეტ მოციქულთაგანი იყო და ეკლესიაში იაკობის ძმადაც მოიხსენიება.','Jude was one of the Twelve Apostles and is also known in the Church as the brother of James. Church tradition remembers his preaching after Pentecost. His short epistle calls Christians to remain faithful and to live in the love of God.','یەهودا یەکێک لە دوازدە نێردراوەکە بوو و لە کڵێسادا بە برای یاقوبیش ناسراوە. نەریتی کڵێسا مژدەبەریی ئەو دوای پەنجاکۆست یاد دەکاتەوە. نامە کورتەکەی بانگی مەسیحییەکان دەکات بۆ وەفادارمانەوە و ژیان لە خۆشەویستیی خودادا.','იუდა თორმეტ მოციქულთაგანი იყო და ეკლესიაში იაკობის ძმადაც მოიხსენიება. საეკლესიო გადმოცემა სულთმოფენობის შემდეგ მის ქადაგებას იხსენებს. მის მოკლე ეპისტოლეში ქრისტიანები რწმენის ერთგულებისა და ღვთის სიყვარულში ცხოვრებისკენ არიან მოწოდებული.','Apostle','نێردراو','მოციქული','/icons/saints/jude.webp','https://www.oca.org/saints/lives/2026/06/19/101752-apostle-jude-the-brother-of-the-lord','Traditional Orthodox icon published by the Orthodox Church in America. See the linked source for attribution.','https://www.oca.org/saints/lives/2026/06/19/101752-apostle-jude-the-brother-of-the-lord','Orthodox Church in America, Lives of the Saints — Saint Jude the Apostle',array['Jude Thaddeus','Judas not Iscariot','იუდა იაკობის ძმა']::text[],'Saint Jude the Apostle — traditional Orthodox icon','წმინდა იუდა მოციქული — მართლმადიდებლური ხატი','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა იუდა მოციქული
https://www.oca.org/saints/lives/2026/06/19/101752-apostle-jude-the-brother-of-the-lord','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/06/19/101752-apostle-jude-the-brother-of-the-lord',true,113,'saints-expansion-2026:jude' where not exists(select 1 from public.authors where slug='jude' or legacy_key='saints-expansion-2026:jude' or lower(name_en)=lower('Saint Jude the Apostle')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_credit_ka,published,sort_order,legacy_key) select 'cyril-alexandria','Saint Cyril of Alexandria','پایەپیرۆز کیریلۆسی ئەسکەندەری','წმინდა კირილე ალექსანდრიელი','9 June','٩ی حوزەیران','9 ივნისი','Cyril was Archbishop of Alexandria in the fifth century. Against the teaching of Nestorius, he defended the unity of the incarnate Christ and the confession of the Virgin Mary as Theotokos.','کیریلۆس لە سەدەی پێنجەمدا سەرئەسقوفی ئەسکەندەری بوو. لە دژی فێرکاریی نەستۆریۆس، بەرگری لە یەکێتیی کەسایەتیی مەسیحی مرۆڤبوو و داننان بە مەریەمی پاک وەک دایکی خودا کرد.','კირილე V საუკუნეში ალექსანდრიის მთავარეპისკოპოსი იყო. ნესტორის მოძღვრების წინააღმდეგ იგი იცავდა განკაცებული ქრისტეს პიროვნულ ერთობას და ქალწულ მარიამის ღვთისმშობლად აღიარებას.','Cyril was Archbishop of Alexandria in the fifth century.','کیریلۆس لە سەدەی پێنجەمدا سەرئەسقوفی ئەسکەندەری بوو.','კირილე V საუკუნეში ალექსანდრიის მთავარეპისკოპოსი იყო.','/icons/saints/cyril-alexandria.webp','https://www.oca.org/saints/lives/2026/06/09/101595-saint-cyril-archbishop-of-alexandria','Traditional Orthodox icon displayed by the Orthodox Church in America. Artist not identified by the source; image rights remain with their holders.','https://www.oca.org/saints/lives/2026/06/09/101595-saint-cyril-archbishop-of-alexandria','Orthodox Church in America, Lives of the Saints: Cyril of Alexandria','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: კირილე ალექსანდრიელი','Saint Cyril of Alexandria — traditional Orthodox icon','წმინდა კირილე ალექსანდრიელი — მართლმადიდებლური ხატი',array['Cyril of Alexandria','Kyrillos of Alexandria','კირილე ალექსანდრიელი']::text[],'saint-and-father','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/06/09/101595-saint-cyril-archbishop-of-alexandria',true,114,'saints-expansion-2026:cyril-alexandria' where not exists(select 1 from public.authors where slug='cyril-alexandria' or legacy_key='saints-expansion-2026:cyril-alexandria' or lower(name_en)=lower('Saint Cyril of Alexandria')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_license_url,icon_credit_ka,published,sort_order,legacy_key) select 'cyril-jerusalem','Saint Cyril of Jerusalem','پایەپیرۆز کیریلۆسی ئۆرشەلیم','წმინდა კირილე იერუსალიმელი','18 March','١٨ی ئازار','18 მარტი','Cyril served as Bishop of Jerusalem in the fourth century and endured exile during the Arian controversies. His catechetical lectures explain the Christian faith and the mysteries of initiation to candidates for Baptism and the newly baptized.','کیریلۆس لە سەدەی چوارەمدا ئەسقوفی ئۆرشەلیم بوو و لە ناکۆکییەکانی ئارێۆسیدا دوورخرایەوە. وتارە فێرکارییەکانی باوەڕی مەسیحی و نهێنییەکانی دەستپێکی ژیانی کڵێسایی بۆ خۆئامادەکەرانی مەعمودیەت و نوێ مەعمودیەتکراوان ڕوون دەکەنەوە.','კირილე IV საუკუნეში იერუსალიმის ეპისკოპოსი იყო და არიანულ დავათა დროს გადასახლება დაითმინა. მის კათაკმევლურ სიტყვებში ქრისტიანული სარწმუნოება და ეკლესიაში მიღების საიდუმლოებები ნათლობისთვის მომზადებულებსა და ახალმონათლულებს განემარტება.','Cyril served as Bishop of Jerusalem in the fourth century and endured exile during the Arian controversies.','کیریلۆس لە سەدەی چوارەمدا ئەسقوفی ئۆرشەلیم بوو و لە ناکۆکییەکانی ئارێۆسیدا دوورخرایەوە.','კირილე IV საუკუნეში იერუსალიმის ეპისკოპოსი იყო და არიანულ დავათა დროს გადასახლება დაითმინა.','/icons/saints/cyril-jerusalem.webp','https://commons.wikimedia.org/wiki/File:Saint_Cyril_of_Jerusalem.jpg','Anonymous Greek iconographer, fourteenth-century fresco. Public domain; faithful reproduction, Wikimedia Commons.','https://www.oca.org/saints/lives/2026/03/18/100829-saint-cyril-archbishop-of-jerusalem','Orthodox Church in America, Lives of the Saints: Cyril of Jerusalem','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: კირილე იერუსალიმელი','Saint Cyril of Jerusalem — traditional Orthodox icon','წმინდა კირილე იერუსალიმელი — მართლმადიდებლური ხატი',array['Cyril of Jerusalem','Kyrillos of Jerusalem','კირილე იერუსალიმელი']::text[],'saint-and-father','https://creativecommons.org/publicdomain/mark/1.0/','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://commons.wikimedia.org/wiki/File:Saint_Cyril_of_Jerusalem.jpg',true,115,'saints-expansion-2026:cyril-jerusalem' where not exists(select 1 from public.authors where slug='cyril-jerusalem' or legacy_key='saints-expansion-2026:cyril-jerusalem' or lower(name_en)=lower('Saint Cyril of Jerusalem')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_credit_ka,published,sort_order,legacy_key) select 'ignatius-antioch','Saint Ignatius the God-Bearer of Antioch','پایەپیرۆز ئیگناتیۆسی خوداهەڵگری ئەنتاکیا','წმინდა ეგნატე ღმერთშემოსილი','20 December','٢٠ی کانوونی یەکەم','20 დეკემბერი','Ignatius was an early bishop of Antioch who was taken to Rome for martyrdom. His letters to Christian communities bear witness to faith in the incarnate Christ, the Eucharist, and unity around the bishop.','ئیگناتیۆس یەکێک بوو لە ئەسقوفە سەرەتاییەکانی ئەنتاکیا و بۆ شەهیدکردن بردرایە ڕۆما. نامەکانی بۆ کۆمەڵە مەسیحییەکان شایەتیی باوەڕ بە مەسیحی مرۆڤبوو، قوربانیی پیرۆز و یەکێتی لە دەوری ئەسقوف دەدەن.','ეგნატე ანტიოქიის ადრეული ეპისკოპოსი იყო, რომელიც მოწამეობრივი აღსასრულისთვის რომში წაიყვანეს. ქრისტიანული თემებისადმი მისი წერილები მოწმობს განკაცებული ქრისტეს რწმენას, ევქარისტიის მნიშვნელობასა და ეპისკოპოსის გარშემო ერთობას.','Ignatius was an early bishop of Antioch who was taken to Rome for martyrdom.','ئیگناتیۆس یەکێک بوو لە ئەسقوفە سەرەتاییەکانی ئەنتاکیا و بۆ شەهیدکردن بردرایە ڕۆما.','ეგნატე ანტიოქიის ადრეული ეპისკოპოსი იყო, რომელიც მოწამეობრივი აღსასრულისთვის რომში წაიყვანეს.','/icons/saints/ignatius-antioch.webp','https://www.oca.org/saints/lives/2026/12/20/103594-hieromartyr-ignatius-the-god-bearer-bishop-of-antioch','Traditional Orthodox icon displayed by the Orthodox Church in America. Artist not identified by the source; image rights remain with their holders.','https://www.oca.org/saints/lives/2026/12/20/103594-hieromartyr-ignatius-the-god-bearer-bishop-of-antioch','Orthodox Church in America, Lives of the Saints: Ignatius the God-Bearer of Antioch','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: ეგნატე ღმერთშემოსილი','Saint Ignatius the God-Bearer of Antioch — traditional Orthodox icon','წმინდა ეგნატე ღმერთშემოსილი — მართლმადიდებლური ხატი',array['Ignatius of Antioch','Ignatius the Godbearer','ეგნატე ღმერთშემოსილი']::text[],'saint-and-father','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/12/20/103594-hieromartyr-ignatius-the-god-bearer-bishop-of-antioch',true,116,'saints-expansion-2026:ignatius-antioch' where not exists(select 1 from public.authors where slug='ignatius-antioch' or legacy_key='saints-expansion-2026:ignatius-antioch' or lower(name_en)=lower('Saint Ignatius the God-Bearer of Antioch')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_credit_ka,published,sort_order,legacy_key) select 'polycarp-smyrna','Saint Polycarp of Smyrna','پایەپیرۆز پۆلیکارپۆسی سمیرنا','წმინდა პოლიკარპე სმირნელი','23 February','٢٣ی شوبات','23 თებერვალი','Polycarp was Bishop of Smyrna in Asia Minor and belonged to the generation that received the apostolic tradition. He remained faithful to Christ under persecution and suffered martyrdom; the Church also preserves his Letter to the Philippians.','پۆلیکارپۆس ئەسقوفی سمیرنا لە ئاسیای بچووک بوو و سەر بەو نەوەیە بوو کە نەریتی نێردراوانیان وەرگرت. لە ژێر چەوساندنەوەدا بە مەسیح وەفادار مایەوە و شەهید کرا؛ کڵێسا نامەکەشی بۆ فیلیپییەکان پاراستووە.','პოლიკარპე მცირე აზიაში, სმირნის ეპისკოპოსი იყო და იმ თაობას ეკუთვნოდა, რომელმაც სამოციქულო გადმოცემა მიიღო. დევნის დროს იგი ქრისტეს ერთგული დარჩა და მოწამეობრივად აღესრულა; ეკლესიამ შემოინახა მისი წერილიც ფილიპელთა მიმართ.','Polycarp was Bishop of Smyrna in Asia Minor and belonged to the generation that received the apostolic tradition.','پۆلیکارپۆس ئەسقوفی سمیرنا لە ئاسیای بچووک بوو و سەر بەو نەوەیە بوو کە نەریتی نێردراوانیان وەرگرت.','პოლიკარპე მცირე აზიაში, სმირნის ეპისკოპოსი იყო და იმ თაობას ეკუთვნოდა, რომელმაც სამოციქულო გადმოცემა მიიღო.','/icons/saints/polycarp-smyrna.webp','https://www.oca.org/saints/lives/2026/02/23/100589-hieromartyr-polycarp-bishop-of-smyrna','Traditional Orthodox icon displayed by the Orthodox Church in America. Artist not identified by the source; image rights remain with their holders.','https://www.oca.org/saints/lives/2026/02/23/100589-hieromartyr-polycarp-bishop-of-smyrna','Orthodox Church in America, Lives of the Saints: Polycarp of Smyrna','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: პოლიკარპე სმირნელი','Saint Polycarp of Smyrna — traditional Orthodox icon','წმინდა პოლიკარპე სმირნელი — მართლმადიდებლური ხატი',array['Polycarp of Smyrna','პოლიკარპე სმირნელი']::text[],'saint-and-father','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/02/23/100589-hieromartyr-polycarp-bishop-of-smyrna',true,117,'saints-expansion-2026:polycarp-smyrna' where not exists(select 1 from public.authors where slug='polycarp-smyrna' or legacy_key='saints-expansion-2026:polycarp-smyrna' or lower(name_en)=lower('Saint Polycarp of Smyrna')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_credit_ka,published,sort_order,legacy_key) select 'irenaeus-lyons','Saint Irenaeus of Lyons','پایەپیرۆز ئیرینایۆسی لیۆن','წმინდა ირინეოს ლიონელი','23 August','٢٣ی ئاب','23 აგვისტო','Irenaeus, who learned from Polycarp of Smyrna, became Bishop of Lyons in Gaul in the second century. His work Against Heresies defended the apostolic faith against Gnostic teachings and emphasized the unity of God’s saving work.','ئیرینایۆس، کە لە پۆلیکارپۆسی سمیرنا فێر بوو، لە سەدەی دووەمدا بوو بە ئەسقوفی لیۆن لە گالیا. بەرهەمەکەی بە ناوی دژی هەرەسییەکان بەرگری لە باوەڕی نێردراوان لە دژی فێرکارییە گنۆسییەکان کرد و جەختی لە یەکێتیی کاری ڕزگارکەری خودا کردەوە.','ირინეოსი, რომელიც პოლიკარპე სმირნელისგან სწავლობდა, II საუკუნეში გალიის ქალაქ ლიონის ეპისკოპოსი გახდა. ნაშრომში „მწვალებლობათა წინააღმდეგ“ იგი გნოსტიკური სწავლებებისგან იცავდა სამოციქულო სარწმუნოებას და ღვთის მაცხოვნებელი მოქმედების ერთობას უსვამდა ხაზს.','Irenaeus, who learned from Polycarp of Smyrna, became Bishop of Lyons in Gaul in the second century.','ئیرینایۆس، کە لە پۆلیکارپۆسی سمیرنا فێر بوو، لە سەدەی دووەمدا بوو بە ئەسقوفی لیۆن لە گالیا.','ირინეოსი, რომელიც პოლიკარპე სმირნელისგან სწავლობდა, II საუკუნეში გალიის ქალაქ ლიონის ეპისკოპოსი გახდა.','/icons/saints/irenaeus-lyons.webp','https://www.oca.org/saints/lives/2026/08/23/102379-hieromartyr-irenaeus-bishop-of-lyons','Traditional Orthodox icon displayed by the Orthodox Church in America. Artist not identified by the source; image rights remain with their holders.','https://www.oca.org/saints/lives/2026/08/23/102379-hieromartyr-irenaeus-bishop-of-lyons','Orthodox Church in America, Lives of the Saints: Irenaeus of Lyons','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: ირინეოს ლიონელი','Saint Irenaeus of Lyons — traditional Orthodox icon','წმინდა ირინეოს ლიონელი — მართლმადიდებლური ხატი',array['Irenaeus of Lyon','Irenaeus of Lyons','ირინეოს ლიონელი']::text[],'saint-and-father','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/08/23/102379-hieromartyr-irenaeus-bishop-of-lyons',true,118,'saints-expansion-2026:irenaeus-lyons' where not exists(select 1 from public.authors where slug='irenaeus-lyons' or legacy_key='saints-expansion-2026:irenaeus-lyons' or lower(name_en)=lower('Saint Irenaeus of Lyons')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_credit_ka,published,sort_order,legacy_key) select 'justin-martyr','Saint Justin the Philosopher and Martyr','پایەپیرۆز یوستینی فەیلەسوف و شەهید','წმინდა იუსტინე ფილოსოფოსი და მოწამე','1 June','١ی حوزەیران','1 ივნისი','Justin was a second-century Christian teacher who had studied Greek philosophy before receiving Baptism. He defended Christianity in his Apologies and was martyred at Rome with fellow Christians.','یوستین مامۆستایەکی مەسیحیی سەدەی دووەم بوو کە پێش وەرگرتنی مەعمودیەت فەلسەفەی یۆنانی خوێندبوو. لە نووسینە بەرگرییەکانی خۆیدا بەرگری لە مەسیحییەت کرد و لە ڕۆما لەگەڵ چەند مەسیحییەکی دیکە شەهید کرا.','იუსტინე II საუკუნის ქრისტიანი მოძღვარი იყო, რომელმაც ნათლობამდე ბერძნული ფილოსოფია შეისწავლა. თავის „აპოლოგიებში“ იგი ქრისტიანობას იცავდა და სხვა ქრისტიანებთან ერთად რომში მოწამეობრივად აღესრულა.','Justin was a second-century Christian teacher who had studied Greek philosophy before receiving Baptism.','یوستین مامۆستایەکی مەسیحیی سەدەی دووەم بوو کە پێش وەرگرتنی مەعمودیەت فەلسەفەی یۆنانی خوێندبوو.','იუსტინე II საუკუნის ქრისტიანი მოძღვარი იყო, რომელმაც ნათლობამდე ბერძნული ფილოსოფია შეისწავლა.','/icons/saints/justin-martyr.webp','https://www.oca.org/saints/lives/2026/06/01/101570-martyr-justin-the-philosopher-and-those-with-him-at-rome','Traditional Orthodox icon displayed by the Orthodox Church in America. Artist not identified by the source; image rights remain with their holders.','https://www.oca.org/saints/lives/2026/06/01/101570-martyr-justin-the-philosopher-and-those-with-him-at-rome','Orthodox Church in America, Lives of the Saints: Justin the Philosopher and Martyr','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: იუსტინე ფილოსოფოსი და მოწამე','Saint Justin the Philosopher and Martyr — traditional Orthodox icon','წმინდა იუსტინე ფილოსოფოსი და მოწამე — მართლმადიდებლური ხატი',array['Justin Martyr','Justin the Philosopher','იუსტინე ფილოსოფოსი']::text[],'saint-and-father','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/06/01/101570-martyr-justin-the-philosopher-and-those-with-him-at-rome',true,119,'saints-expansion-2026:justin-martyr' where not exists(select 1 from public.authors where slug='justin-martyr' or legacy_key='saints-expansion-2026:justin-martyr' or lower(name_en)=lower('Saint Justin the Philosopher and Martyr')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_credit_ka,published,sort_order,legacy_key) select 'cyprian-carthage','Saint Cyprian of Carthage','پایەپیرۆز کیپریانی قەرتاج','წმინდა კვიპრიანე კართაგენელი','31 August','٣١ی ئاب','31 აგვისტო','Cyprian was a teacher of rhetoric before becoming a Christian and Bishop of Carthage in North Africa. His writings address the unity of the Church and repentance after persecution; he was executed for his Christian faith in 258.','کیپریان پێش ئەوەی مەسیحی ببێت و ببێتە ئەسقوفی قەرتاج لە باکووری ئەفریقا، مامۆستای ڕەوانبێژی بوو. نووسینەکانی باس لە یەکێتیی کڵێسا و تەوبە دوای چەوساندنەوە دەکەن؛ لە ساڵی ٢٥٨دا لەبەر باوەڕە مەسیحییەکەی لە سێدارە درا.','კვიპრიანე ქრისტიანად მოქცევამდე და ჩრდილოეთ აფრიკაში კართაგენის ეპისკოპოსად დადგინებამდე რიტორიკის მასწავლებელი იყო. მისი თხზულებები ეკლესიის ერთობასა და დევნის შემდეგ სინანულს ეხება; 258 წელს იგი ქრისტეს რწმენისთვის სიკვდილით დასაჯეს.','Cyprian was a teacher of rhetoric before becoming a Christian and Bishop of Carthage in North Africa.','کیپریان پێش ئەوەی مەسیحی ببێت و ببێتە ئەسقوفی قەرتاج لە باکووری ئەفریقا، مامۆستای ڕەوانبێژی بوو.','კვიპრიანე ქრისტიანად მოქცევამდე და ჩრდილოეთ აფრიკაში კართაგენის ეპისკოპოსად დადგინებამდე რიტორიკის მასწავლებელი იყო.','/icons/saints/cyprian-carthage.webp','https://www.oca.org/saints/lives/2026/08/31/102443-hieromartyr-cyprian-bishop-of-carthage','Traditional Orthodox icon displayed by the Orthodox Church in America. Artist not identified by the source; image rights remain with their holders.','https://www.oca.org/saints/lives/2026/08/31/102443-hieromartyr-cyprian-bishop-of-carthage','Orthodox Church in America, Lives of the Saints: Cyprian of Carthage','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: კვიპრიანე კართაგენელი','Saint Cyprian of Carthage — traditional Orthodox icon','წმინდა კვიპრიანე კართაგენელი — მართლმადიდებლური ხატი',array['Cyprian of Carthage','Thascius Cyprianus','კვიპრიანე კართაგენელი']::text[],'saint-and-father','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/08/31/102443-hieromartyr-cyprian-bishop-of-carthage',true,120,'saints-expansion-2026:cyprian-carthage' where not exists(select 1 from public.authors where slug='cyprian-carthage' or legacy_key='saints-expansion-2026:cyprian-carthage' or lower(name_en)=lower('Saint Cyprian of Carthage')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_credit_ka,published,sort_order,legacy_key) select 'gregory-palamas','Saint Gregory Palamas','پایەپیرۆز گریگۆری پەلاماس','წმინდა გრიგოლ პალამა','14 November','١٤ی تشرینی دووەم','14 ნოემბერი','Gregory Palamas was an Athonite monk and later Archbishop of Thessalonica in the fourteenth century. He defended hesychastic prayer and taught the distinction between God’s inaccessible essence and His uncreated energies, through which people truly participate in divine life.','گریگۆری پەلاماس لە سەدەی چواردەیەمدا تاکمەندی ئاتۆس و دواتر سەرئەسقوفی تەسالۆنیکی بوو. بەرگری لە نوێژی هێسیکاستی کرد و جیاوازیی نێوان ناوەڕۆکی دەستپێنەگەیشتووی خودا و وزە نەخوڵقێنراوەکانی فێر کرد، کە مرۆڤ بەهۆیانەوە بەڕاستی بەشدار لە ژیانی خودایی دەبێت.','გრიგოლ პალამა XIV საუკუნეში ათონელი ბერი, შემდეგ კი თესალონიკის მთავარეპისკოპოსი იყო. იგი იცავდა ისიქასტურ ლოცვას და ასწავლიდა განსხვავებას ღვთის მიუწვდომელ არსებასა და მის უქმნელ ენერგიებს შორის, რომელთა მეშვეობით ადამიანი რეალურად ეზიარება ღვთაებრივ ცხოვრებას.','Gregory Palamas was an Athonite monk and later Archbishop of Thessalonica in the fourteenth century.','گریگۆری پەلاماس لە سەدەی چواردەیەمدا تاکمەندی ئاتۆس و دواتر سەرئەسقوفی تەسالۆنیکی بوو.','გრიგოლ პალამა XIV საუკუნეში ათონელი ბერი, შემდეგ კი თესალონიკის მთავარეპისკოპოსი იყო.','/icons/saints/gregory-palamas.webp','https://www.oca.org/saints/lives/2026/11/14/103303-saint-gregory-palamas-archbishop-of-thessalonica','Traditional Orthodox icon displayed by the Orthodox Church in America. Artist not identified by the source; image rights remain with their holders.','https://www.oca.org/saints/lives/2026/11/14/103303-saint-gregory-palamas-archbishop-of-thessalonica','Orthodox Church in America, Lives of the Saints: Gregory Palamas','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: გრიგოლ პალამა','Saint Gregory Palamas — traditional Orthodox icon','წმინდა გრიგოლ პალამა — მართლმადიდებლური ხატი',array['Gregory Palamas','Gregorios Palamas','გრიგოლ პალამა']::text[],'saint-and-father','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/11/14/103303-saint-gregory-palamas-archbishop-of-thessalonica',true,121,'saints-expansion-2026:gregory-palamas' where not exists(select 1 from public.authors where slug='gregory-palamas' or legacy_key='saints-expansion-2026:gregory-palamas' or lower(name_en)=lower('Saint Gregory Palamas')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_credit_ka,published,sort_order,legacy_key) select 'seraphim-sarov','Saint Seraphim of Sarov','پایەپیرۆز سەرافیمی سارۆڤ','წმინდა სერაფიმე საროველი','2 January','٢ی کانوونی دووەم','2 იანვარი','Seraphim was a monk and spiritual elder of the Sarov monastery in Russia, living in the eighteenth and nineteenth centuries. After years of solitude and prayer, he received visitors seeking spiritual counsel and became especially remembered for humility, mercy, and life in the Holy Spirit.','سەرافیم لە سەدەکانی هەژدە و نۆزدەدا تاکمەند و پیرێکی ڕۆحانیی دێری سارۆڤ لە ڕووسیا بوو. دوای چەندین ساڵ گۆشەگیری و نوێژ، پێشوازی لە سەردانکەرانی داواکاری ڕێنماییی ڕۆحی کرد و بە تایبەتی بە خاکەڕایی، بەزەیی و ژیان لە ڕۆحی پیرۆزدا ناسراوە.','სერაფიმე XVIII–XIX საუკუნეებში რუსეთში, საროვის მონასტერში მოღვაწე ბერი და სულიერი მოძღვარი იყო. განმარტოებასა და ლოცვაში გატარებული წლების შემდეგ იგი სულიერი რჩევის მაძიებლებს იღებდა და განსაკუთრებით თავმდაბლობით, მოწყალებითა და სულიწმიდაში ცხოვრებით არის ცნობილი.','Seraphim was a monk and spiritual elder of the Sarov monastery in Russia, living in the eighteenth and nineteenth centuries.','سەرافیم لە سەدەکانی هەژدە و نۆزدەدا تاکمەند و پیرێکی ڕۆحانیی دێری سارۆڤ لە ڕووسیا بوو.','სერაფიმე XVIII–XIX საუკუნეებში რუსეთში, საროვის მონასტერში მოღვაწე ბერი და სულიერი მოძღვარი იყო.','/icons/saints/seraphim-sarov.webp','https://www.oca.org/saints/lives/2026/01/02/100008-repose-of-venerable-seraphim-wonderworker-of-sarov','Traditional Orthodox icon displayed by the Orthodox Church in America. Artist not identified by the source; image rights remain with their holders.','https://www.oca.org/saints/lives/2026/01/02/100008-repose-of-venerable-seraphim-wonderworker-of-sarov','Orthodox Church in America, Lives of the Saints: Seraphim of Sarov','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: სერაფიმე საროველი','Saint Seraphim of Sarov — traditional Orthodox icon','წმინდა სერაფიმე საროველი — მართლმადიდებლური ხატი',array['Seraphim of Sarov','Prochorus Moshnin','სერაფიმე საროველი']::text[],'saint-and-father','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/01/02/100008-repose-of-venerable-seraphim-wonderworker-of-sarov',true,122,'saints-expansion-2026:seraphim-sarov' where not exists(select 1 from public.authors where slug='seraphim-sarov' or legacy_key='saints-expansion-2026:seraphim-sarov' or lower(name_en)=lower('Saint Seraphim of Sarov')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_license_url,icon_credit_ka,published,sort_order,legacy_key) select 'sergius-radonezh','Saint Sergius of Radonezh','پایەپیرۆز سەرگیۆسی ڕادۆنیژ','წმინდა სერგი რადონეჟელი','25 September','٢٥ی ئەیلوول','25 სექტემბერი','Sergius was a fourteenth-century Russian monk who founded a monastery dedicated to the Holy Trinity near Radonezh. His community became an important center of monastic life, and his disciples established other monasteries.','سەرگیۆس تاکمەندێکی ڕووسیی سەدەی چواردەیەم بوو کە لە نزیک ڕادۆنیژ دێرێکی بۆ سێیەکی پیرۆز دامەزراند. کۆمەڵەکەی بوو بە ناوەندێکی گرنگی ژیانی تاکمەندی و شاگردەکانی دێری دیکەیان دامەزراند.','სერგი XIV საუკუნის რუსი ბერი იყო, რომელმაც რადონეჟის მახლობლად წმინდა სამების სახელობის მონასტერი დააარსა. მისი სავანე სამონასტრო ცხოვრების მნიშვნელოვან ცენტრად იქცა, მისმა მოწაფეებმა კი სხვა მონასტრები დააფუძნეს.','Sergius was a fourteenth-century Russian monk who founded a monastery dedicated to the Holy Trinity near Radonezh.','سەرگیۆس تاکمەندێکی ڕووسیی سەدەی چواردەیەم بوو کە لە نزیک ڕادۆنیژ دێرێکی بۆ سێیەکی پیرۆز دامەزراند.','სერგი XIV საუკუნის რუსი ბერი იყო, რომელმაც რადონეჟის მახლობლად წმინდა სამების სახელობის მონასტერი დააარსა.','/icons/saints/sergius-radonezh.webp','https://commons.wikimedia.org/wiki/File:Sergius_of_Radonezh_begin_of_16c_SPMZ.jpg','Anonymous Moscow iconographer, early sixteenth century. Sergius of Radonezh with scenes from his life. Public domain; Wikimedia Commons.','https://www.oca.org/saints/lives/2026/09/25/102725-repose-of-venerable-sergius-the-wonderworker-abbot-of-radonezh','Orthodox Church in America, Lives of the Saints: Sergius of Radonezh','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: სერგი რადონეჟელი','Saint Sergius of Radonezh — traditional Orthodox icon','წმინდა სერგი რადონეჟელი — მართლმადიდებლური ხატი',array['Sergius of Radonezh','Sergei of Radonezh','სერგი რადონეჟელი']::text[],'saint-and-father','https://creativecommons.org/publicdomain/mark/1.0/','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://commons.wikimedia.org/wiki/File:Sergius_of_Radonezh_begin_of_16c_SPMZ.jpg',true,123,'saints-expansion-2026:sergius-radonezh' where not exists(select 1 from public.authors where slug='sergius-radonezh' or legacy_key='saints-expansion-2026:sergius-radonezh' or lower(name_en)=lower('Saint Sergius of Radonezh')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_credit_ka,published,sort_order,legacy_key) select 'mary-egypt','Saint Mary of Egypt','پایەپیرۆز مەریەمی میسری','წმინდა მარიამ ეგვიპტელი','1 April','١ی نیسان','1 აპრილი','Mary of Egypt is venerated as a desert ascetic and an example of profound repentance. Her traditional Life recounts her conversion in Jerusalem, many years of ascetic struggle beyond the Jordan, and her meeting with the monk Zosimas.','مەریەمی میسری وەک زاهدێکی بیابان و نموونەیەکی تەوبەی قووڵ ڕێزی لێ دەگیرێت. ژیاننامە نەریتییەکەی باس لە گۆڕانی ژیانی لە ئۆرشەلیم، چەندین ساڵ تێکۆشانی زاهدانە لە دیوی ئەوبەری ئوردون و دیداری لەگەڵ تاکمەند زۆسیماس دەکات.','მარიამ ეგვიპტელს ეკლესია უდაბნოს მოღვაწედ და ღრმა სინანულის მაგალითად მიაგებს პატივს. მისი ტრადიციული ცხოვრება მოგვითხრობს იერუსალიმში მოქცევაზე, იორდანის გაღმა მრავალწლიან ასკეტურ ღვაწლსა და ბერ ზოსიმესთან შეხვედრაზე.','Mary of Egypt is venerated as a desert ascetic and an example of profound repentance.','مەریەمی میسری وەک زاهدێکی بیابان و نموونەیەکی تەوبەی قووڵ ڕێزی لێ دەگیرێت.','მარიამ ეგვიპტელს ეკლესია უდაბნოს მოღვაწედ და ღრმა სინანულის მაგალითად მიაგებს პატივს.','/icons/saints/mary-egypt.webp','https://www.oca.org/saints/lives/2026/04/01/100963-venerable-mary-of-egypt','Traditional Orthodox icon displayed by the Orthodox Church in America. Artist not identified by the source; image rights remain with their holders.','https://www.oca.org/saints/lives/2026/04/01/100963-venerable-mary-of-egypt','Orthodox Church in America, Lives of the Saints: Mary of Egypt','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: მარიამ ეგვიპტელი','Saint Mary of Egypt — traditional Orthodox icon','წმინდა მარიამ ეგვიპტელი — მართლმადიდებლური ხატი',array['Mary of Egypt','Maria of Egypt','მარიამ ეგვიპტელი']::text[],'saint-and-father','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://www.oca.org/saints/lives/2026/04/01/100963-venerable-mary-of-egypt',true,124,'saints-expansion-2026:mary-egypt' where not exists(select 1 from public.authors where slug='mary-egypt' or legacy_key='saints-expansion-2026:mary-egypt' or lower(name_en)=lower('Saint Mary of Egypt')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,biography_en,biography_ckb,biography_ka,summary_en,summary_ckb,summary_ka,icon_url,icon_source,icon_credit,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,aliases,kind,icon_license_url,icon_credit_ka,published,sort_order,legacy_key) select 'macarius-great','Saint Macarius the Great of Egypt','پایەپیرۆز مەکاریۆسی مەزنی میسری','წმინდა მაკარი დიდი ეგვიპტელი','19 January','١٩ی کانوونی دووەم','19 იანვარი','Macarius was a fourth-century Egyptian monk and priest associated with the desert of Scetis. He became a spiritual guide to other monks and is remembered among the Desert Fathers for prayer, humility, and mercy.','مەکاریۆس تاکمەند و قەشەیەکی میسریی سەدەی چوارەم بوو کە پەیوەندی بە بیابانی سکێتیسەوە هەبوو. بوو بە ڕێنماییکەرێکی ڕۆحی بۆ تاکمەندانی دیکە و لە نێو باوکانی بیاباندا بە نوێژ، خاکەڕایی و بەزەیی یاد دەکرێتەوە.','მაკარი IV საუკუნის ეგვიპტელი ბერი და მღვდელი იყო, რომელიც სკიტის უდაბნოში მოღვაწეობდა. იგი სხვა ბერების სულიერი წინამძღვარი გახდა და უდაბნოს მამათა შორის ლოცვით, თავმდაბლობითა და მოწყალებით არის ცნობილი.','Macarius was a fourth-century Egyptian monk and priest associated with the desert of Scetis.','مەکاریۆس تاکمەند و قەشەیەکی میسریی سەدەی چوارەم بوو کە پەیوەندی بە بیابانی سکێتیسەوە هەبوو.','მაკარი IV საუკუნის ეგვიპტელი ბერი და მღვდელი იყო, რომელიც სკიტის უდაბნოში მოღვაწეობდა.','/icons/saints/macarius-great.webp','https://commons.wikimedia.org/wiki/File:Icon_of_Saint_Macarius_the_Great.jpg','Anonymous traditional Russian Orthodox icon, before the nineteenth century. Public domain; Wikimedia Commons.','https://www.oca.org/saints/lives/2026/01/19/100226-venerable-macarius-the-great-of-egypt','Orthodox Church in America, Lives of the Saints: Macarius the Great of Egypt','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: მაკარი დიდი ეგვიპტელი','Saint Macarius the Great of Egypt — traditional Orthodox icon','წმინდა მაკარი დიდი ეგვიპტელი — მართლმადიდებლური ხატი',array['Macarius of Egypt','Macarius the Elder','Makarios the Great','მაკარი დიდი']::text[],'saint-and-father','https://creativecommons.org/publicdomain/mark/1.0/','ტრადიციული მართლმადიდებლური ხატი. წყარო: https://commons.wikimedia.org/wiki/File:Icon_of_Saint_Macarius_the_Great.jpg',true,125,'saints-expansion-2026:macarius-great' where not exists(select 1 from public.authors where slug='macarius-great' or legacy_key='saints-expansion-2026:macarius-great' or lower(name_en)=lower('Saint Macarius the Great of Egypt')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'matthias-apostle','Saint Matthias the Apostle','پایەپیرۆز مەتیاسی نێردراو','წმინდა მატათა მოციქული','August 9','٩ی ئاب','9 აგვისტო','Matthias was chosen to join the Twelve Apostles after the Ascension of Christ, as recorded in Acts 1:15–26.','مەتیاس دوای بەرزبوونەوەی مەسیح هەڵبژێردرا بۆ پەیوەستبوون بە دوازدە نێردراوەکە، وەک لە کردارەکان ١:١٥–٢٦ هاتووە.','ქრისტეს ამაღლების შემდეგ მატათა თორმეტი მოციქულის დასში აირჩიეს, როგორც ეს მოციქულთა საქმეების 1:15–26-შია აღწერილი.','Matthias was chosen to join the Twelve Apostles after the Ascension of Christ, as recorded in Acts 1:15–26. He preached the Gospel with the apostolic community.','مەتیاس دوای بەرزبوونەوەی مەسیح هەڵبژێردرا بۆ پەیوەستبوون بە دوازدە نێردراوەکە، وەک لە کردارەکان ١:١٥–٢٦ هاتووە. ئەو لەگەڵ کۆمەڵەی نێردراوان مزگێنی ڕاگەیاند.','ქრისტეს ამაღლების შემდეგ მატათა თორმეტი მოციქულის დასში აირჩიეს, როგორც ეს მოციქულთა საქმეების 1:15–26-შია აღწერილი. იგი მოციქულებთან ერთად ქადაგებდა სახარებას.',array['Matthias','Matthias the Apostle','მატათა']::text[],'saint','/icons/saints/matthias-apostle.webp','https://www.oca.org/saints/lives/2026/08/09/102243-apostle-matthias-of-the-seventy','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://www.oca.org/saints/lives/2026/08/09/102243-apostle-matthias-of-the-seventy','Orthodox Church in America, Lives of the Saints: Saint Matthias the Apostle; August 9.','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა მატათა მოციქული; 9 აგვისტო.','Saint Matthias the Apostle — traditional Orthodox icon','წმინდა მატათა მოციქული — მართლმადიდებლური ხატი',true,126,'saints-expansion-2026:matthias-apostle' where not exists(select 1 from public.authors where slug='matthias-apostle' or legacy_key='saints-expansion-2026:matthias-apostle' or lower(name_en)=lower('Saint Matthias the Apostle')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'stephen-protomartyr','Saint Stephen the Protomartyr','پایەپیرۆز ستیفانۆسی یەکەم شەهید','წმინდა სტეფანე პირველმოწამე','December 27','٢٧ی کانوونی یەکەم','27 დეკემბერი','Stephen was one of the seven men appointed to serve the early Christian community in Jerusalem.','ستیفانۆس یەکێک بوو لەو حەوت پیاوەی بۆ خزمەتی کۆمەڵگەی سەرەتایی مەسیحی لە ئۆرشەلیم دیاری کران.','სტეფანე ერთ-ერთი იყო იმ შვიდი კაციდან, რომლებიც იერუსალიმის პირველ ქრისტიანულ თემში მსახურებისთვის აირჩიეს.','Stephen was one of the seven men appointed to serve the early Christian community in Jerusalem. Acts 6–7 recounts his witness to Christ and his death by stoning; the Church venerates him as the first martyr.','ستیفانۆس یەکێک بوو لەو حەوت پیاوەی بۆ خزمەتی کۆمەڵگەی سەرەتایی مەسیحی لە ئۆرشەلیم دیاری کران. کردارەکان ٦–٧ شایەتیدانی بۆ مەسیح و مردنی بە بەردباران دەگێڕێتەوە؛ کڵێسا وەک یەکەم شەهید ڕێزی لێ دەگرێت.','სტეფანე ერთ-ერთი იყო იმ შვიდი კაციდან, რომლებიც იერუსალიმის პირველ ქრისტიანულ თემში მსახურებისთვის აირჩიეს. მოციქულთა საქმეების 6–7 თავებში მოთხრობილია მისი მოწმობა ქრისტეზე და ქვებით ჩაქოლვა; ეკლესია მას პირველმოწამედ პატივს მიაგებს.',array['Stephen','Stephen the Protomartyr','სტეფანე']::text[],'saint','/icons/saints/stephen-protomartyr.webp','https://www.oca.org/saints/lives/2026/12/27/103659-protomartyr-and-archdeacon-stephen','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://www.oca.org/saints/lives/2026/12/27/103659-protomartyr-and-archdeacon-stephen','Orthodox Church in America, Lives of the Saints: Saint Stephen the Protomartyr; December 27.','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა სტეფანე პირველმოწამე; 27 დეკემბერი.','Saint Stephen the Protomartyr — traditional Orthodox icon','წმინდა სტეფანე პირველმოწამე — მართლმადიდებლური ხატი',true,127,'saints-expansion-2026:stephen-protomartyr' where not exists(select 1 from public.authors where slug='stephen-protomartyr' or legacy_key='saints-expansion-2026:stephen-protomartyr' or lower(name_en)=lower('Saint Stephen the Protomartyr')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'mary-magdalene','Saint Mary Magdalene','پایەپیرۆز مەریەمی مەجدەلی','წმინდა მარიამ მაგდალინელი','July 22','٢٢ی تەمووز','22 ივლისი','Mary Magdalene followed Jesus and was present at His Crucifixion.','مەریەمی مەجدەلی شوێنی عیسای کەوت و لە کاتی خاچدرانیدا ئامادە بوو.','მარიამ მაგდალინელი იესოს მიმდევარი იყო და მის ჯვარცმას ესწრებოდა.','Mary Magdalene followed Jesus and was present at His Crucifixion. The Gospels describe her visit to His tomb and her witness to the Resurrection; the Orthodox Church honours her among the Myrrhbearers and as Equal-to-the-Apostles.','مەریەمی مەجدەلی شوێنی عیسای کەوت و لە کاتی خاچدرانیدا ئامادە بوو. ئینجیلەکان سەردانکردنی گۆڕەکەی و شایەتیدانی بۆ هەستانەوە دەگێڕنەوە؛ کڵێسای ئۆرتۆدۆکس وەک یەکێک لە هەڵگرانی بۆن و هاوشانی نێردراوان ڕێزی لێ دەگرێت.','მარიამ მაგდალინელი იესოს მიმდევარი იყო და მის ჯვარცმას ესწრებოდა. სახარებები მოგვითხრობენ საფლავთან მის მისვლასა და აღდგომის მოწმობაზე; მართლმადიდებელი ეკლესია მას მენელსაცხებლედ და მოციქულთასწორად პატივს მიაგებს.',array['Mary Magdalene','Mary of Magdala','მარიამ მაგდალინელი']::text[],'saint','/icons/saints/mary-magdalene.webp','https://www.oca.org/saints/lives/2026/07/22/102070-myrrhbearer-and-equal-of-the-apostles-mary-magdalene','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://www.oca.org/saints/lives/2026/07/22/102070-myrrhbearer-and-equal-of-the-apostles-mary-magdalene','Orthodox Church in America, Lives of the Saints: Saint Mary Magdalene; July 22.','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა მარიამ მაგდალინელი; 22 ივლისი.','Saint Mary Magdalene — traditional Orthodox icon','წმინდა მარიამ მაგდალინელი — მართლმადიდებლური ხატი',true,128,'saints-expansion-2026:mary-magdalene' where not exists(select 1 from public.authors where slug='mary-magdalene' or legacy_key='saints-expansion-2026:mary-magdalene' or lower(name_en)=lower('Saint Mary Magdalene')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'george-greatmartyr','Saint George the Great Martyr','پایەپیرۆز جۆرجیۆسی شەهیدی مەزن','წმინდა გიორგი დიდმოწამე','April 23','٢٣ی نیسان','23 აპრილი','George is venerated as a Christian soldier and martyr of the early fourth century.','جۆرجیۆس وەک سەربازێکی مەسیحی و شەهیدی سەرەتای سەدەی چوارەم ڕێزی لێ دەگیرێت.','გიორგი IV საუკუნის დასაწყისის ქრისტიან მეომრად და მოწამედ არის ცნობილი.','George is venerated as a Christian soldier and martyr of the early fourth century. The Church remembers his steadfast confession of Christ during the persecution associated with Emperor Diocletian.','جۆرجیۆس وەک سەربازێکی مەسیحی و شەهیدی سەرەتای سەدەی چوارەم ڕێزی لێ دەگیرێت. کڵێسا دانپێدانانی جێگیری بە مەسیح لە سەردەمی چەوساندنەوەی پەیوەست بە ئیمپراتۆر دیۆکلیتیانۆس یاد دەکاتەوە.','გიორგი IV საუკუნის დასაწყისის ქრისტიან მეომრად და მოწამედ არის ცნობილი. ეკლესია იხსენებს ქრისტესადმი მის ურყევ ერთგულებას იმპერატორ დიოკლეტიანეს დროინდელი დევნისას.',array['George','George the Victory-Bearer','გიორგი','Georgios']::text[],'saint','/icons/saints/george-greatmartyr.webp','https://www.oca.org/saints/lives/2026/04/23/101184-greatmartyr-victory-bearer-and-wonderworker-george','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://www.oca.org/saints/lives/2026/04/23/101184-greatmartyr-victory-bearer-and-wonderworker-george','Orthodox Church in America, Lives of the Saints: Saint George the Great Martyr; April 23.','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა გიორგი დიდმოწამე; 23 აპრილი.','Saint George the Great Martyr — traditional Orthodox icon','წმინდა გიორგი დიდმოწამე — მართლმადიდებლური ხატი',true,129,'saints-expansion-2026:george-greatmartyr' where not exists(select 1 from public.authors where slug='george-greatmartyr' or legacy_key='saints-expansion-2026:george-greatmartyr' or lower(name_en)=lower('Saint George the Great Martyr')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'nicholas-myra','Saint Nicholas of Myra','پایەپیرۆز نیکۆلاۆسی میرا','წმინდა ნიკოლოზ მირონლუკიელი','December 6','٦ی کانوونی یەکەم','6 დეკემბერი','Nicholas served as bishop of Myra in Lycia during the fourth century.','نیکۆلاۆس لە سەدەی چوارەمدا ئەسقوفی میرا لە لیکیا بوو.','ნიკოლოზი IV საუკუნეში ლუკიის მირონის ეპისკოპოსი იყო.','Nicholas served as bishop of Myra in Lycia during the fourth century. The Church remembers him for his pastoral care, generosity to people in need, and defence of the Christian faith.','نیکۆلاۆس لە سەدەی چوارەمدا ئەسقوفی میرا لە لیکیا بوو. کڵێسا بە چاودێریی شوانایەتی و بەخشندەیی بۆ هەژاران و پاراستنی باوەڕی مەسیحی یادی دەکاتەوە.','ნიკოლოზი IV საუკუნეში ლუკიის მირონის ეპისკოპოსი იყო. ეკლესია მას იხსენებს სამწყსოზე ზრუნვის, გაჭირვებულთა მიმართ გულუხვობისა და ქრისტიანული სარწმუნოების დაცვისთვის.',array['Nicholas','Nicholas the Wonderworker','Nicholas of Myra','ნიკოლოზ მირონლუკიელი']::text[],'saint','/icons/saints/nicholas-myra.webp','https://www.oca.org/saints/lives/2026/12/06/103484-saint-nicholas-the-wonderworker-archbishop-of-myra-in-lycia','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://www.oca.org/saints/lives/2026/12/06/103484-saint-nicholas-the-wonderworker-archbishop-of-myra-in-lycia','Orthodox Church in America, Lives of the Saints: Saint Nicholas of Myra; December 6.','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა ნიკოლოზ მირონლუკიელი; 6 დეკემბერი.','Saint Nicholas of Myra — traditional Orthodox icon','წმინდა ნიკოლოზ მირონლუკიელი — მართლმადიდებლური ხატი',true,130,'saints-expansion-2026:nicholas-myra' where not exists(select 1 from public.authors where slug='nicholas-myra' or legacy_key='saints-expansion-2026:nicholas-myra' or lower(name_en)=lower('Saint Nicholas of Myra')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'spyridon-tremithus','Saint Spyridon of Tremithus','پایەپیرۆز سپیریدۆنی تریمیثۆس','წმინდა სპირიდონ ტრიმიფუნტელი','December 12','١٢ی کانوونی یەکەم','12 დეკემბერი','Spyridon was a shepherd on Cyprus before becoming bishop of Tremithus in the fourth century.','سپیریدۆن پێش ئەوەی لە سەدەی چوارەمدا ببێتە ئەسقوفی تریمیثۆس، لە قوبرس شوان بوو.','სპირიდონი კვიპროსზე მწყემსად ცხოვრობდა, შემდეგ კი IV საუკუნეში ტრიმიფუნტის ეპისკოპოსი გახდა.','Spyridon was a shepherd on Cyprus before becoming bishop of Tremithus in the fourth century. His life is remembered for simplicity, care for the poor, and steadfast service to the Church.','سپیریدۆن پێش ئەوەی لە سەدەی چوارەمدا ببێتە ئەسقوفی تریمیثۆس، لە قوبرس شوان بوو. ژیانی بە سادەیی و چاودێریی هەژاران و خزمەتی جێگیر بۆ کڵێسا یاد دەکرێتەوە.','სპირიდონი კვიპროსზე მწყემსად ცხოვრობდა, შემდეგ კი IV საუკუნეში ტრიმიფუნტის ეპისკოპოსი გახდა. მის ცხოვრებას ახასიათებდა უბრალოება, ღარიბებზე ზრუნვა და ეკლესიის ერთგული მსახურება.',array['Spyridon','Spiridon','Spyridon of Trimythous','სპირიდონ ტრიმიფუნტელი']::text[],'saint','/icons/saints/spyridon-tremithus.webp','https://www.oca.org/saints/lives/2026/12/12/103526-saint-spyridon-the-wonderworker-bishop-of-tremithus','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://www.oca.org/saints/lives/2026/12/12/103526-saint-spyridon-the-wonderworker-bishop-of-tremithus','Orthodox Church in America, Lives of the Saints: Saint Spyridon of Tremithus; December 12.','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა სპირიდონ ტრიმიფუნტელი; 12 დეკემბერი.','Saint Spyridon of Tremithus — traditional Orthodox icon','წმინდა სპირიდონ ტრიმიფუნტელი — მართლმადიდებლური ხატი',true,131,'saints-expansion-2026:spyridon-tremithus' where not exists(select 1 from public.authors where slug='spyridon-tremithus' or legacy_key='saints-expansion-2026:spyridon-tremithus' or lower(name_en)=lower('Saint Spyridon of Tremithus')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'nectarios-aegina','Saint Nectarios of Aegina','پایەپیرۆز نێکتاریۆسی ئەگینا','წმინდა ნექტარიოს ეგინელი','November 9','٩ی تشرینی دووەم','9 ნოემბერი','Nectarios served as Metropolitan of Pentapolis and later directed the Rizarios ecclesiastical school in Athens.','نێکتاریۆس مێترۆپۆلیتی پێنتاپۆلیس بوو و دواتر قوتابخانەی کڵێسایی ڕیزاریۆسی لە ئەسینا بەڕێوە برد.','ნექტარიოსი პენტაპოლისის მიტროპოლიტი იყო, შემდეგ კი ათენში რიზარიოსის სასულიერო სკოლას ხელმძღვანელობდა.','Nectarios served as Metropolitan of Pentapolis and later directed the Rizarios ecclesiastical school in Athens. He established a women''s monastic community on Aegina and died in 1920, leaving a legacy of pastoral care and spiritual teaching.','نێکتاریۆس مێترۆپۆلیتی پێنتاپۆلیس بوو و دواتر قوتابخانەی کڵێسایی ڕیزاریۆسی لە ئەسینا بەڕێوە برد. لە ئەگینا کۆمەڵگەیەکی تاکمەندیی ژنانی دامەزراند و لە ساڵی ١٩٢٠ کۆچی دوایی کرد؛ میراتێکی چاودێریی شوانایەتی و فێرکاریی ڕۆحی بەجێهێشت.','ნექტარიოსი პენტაპოლისის მიტროპოლიტი იყო, შემდეგ კი ათენში რიზარიოსის სასულიერო სკოლას ხელმძღვანელობდა. მან ეგინაზე დედათა მონასტერი დააარსა და 1920 წელს გარდაიცვალა; მისი მემკვიდრეობა სამწყსოზე ზრუნვასა და სულიერ სწავლებაში გრძელდება.',array['Nectarios','Nectarius','Anastasios Kephalas','ნექტარიოს ეგინელი']::text[],'saint','/icons/saints/nectarios-aegina.webp','https://www.oca.org/saints/lives/2026/11/09/103251-saint-nectarius-kephalas-metropolitan-of-pentapolis','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://www.oca.org/saints/lives/2026/11/09/103251-saint-nectarius-kephalas-metropolitan-of-pentapolis','Orthodox Church in America, Lives of the Saints: Saint Nectarios of Aegina; November 9.','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა ნექტარიოს ეგინელი; 9 ნოემბერი.','Saint Nectarios of Aegina — traditional Orthodox icon','წმინდა ნექტარიოს ეგინელი — მართლმადიდებლური ხატი',true,132,'saints-expansion-2026:nectarios-aegina' where not exists(select 1 from public.authors where slug='nectarios-aegina' or legacy_key='saints-expansion-2026:nectarios-aegina' or lower(name_en)=lower('Saint Nectarios of Aegina')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'pachomius-great','Saint Pachomius the Great','پایەپیرۆز پاخۆمیۆسی مەزن','წმინდა პახუმი დიდი','May 15','١٥ی ئایار','15 მაისი','Pachomius was an Egyptian monk of the fourth century who organised communities in which monks shared prayer, work, and daily life.','پاخۆمیۆس تاکمەندێکی میسریی سەدەی چوارەم بوو کە کۆمەڵگەی تاکمەندانی ڕێک خست بۆ هاوبەشکردنی نوێژ و کار و ژیانی ڕۆژانە.','პახუმი IV საუკუნის ეგვიპტელი ბერი იყო, რომელმაც მონაზვნური თემები მოაწყო საერთო ლოცვის, შრომისა და ყოველდღიური ცხოვრების საფუძველზე.','Pachomius was an Egyptian monk of the fourth century who organised communities in which monks shared prayer, work, and daily life. His monastic foundations and rule helped shape the development of communal monasticism.','پاخۆمیۆس تاکمەندێکی میسریی سەدەی چوارەم بوو کە کۆمەڵگەی تاکمەندانی ڕێک خست بۆ هاوبەشکردنی نوێژ و کار و ژیانی ڕۆژانە. دامەزراوە و ڕێساکەی یارمەتیی پەرەسەندنی ژیانی تاکمەندیی کۆمەڵایەتی دا.','პახუმი IV საუკუნის ეგვიპტელი ბერი იყო, რომელმაც მონაზვნური თემები მოაწყო საერთო ლოცვის, შრომისა და ყოველდღიური ცხოვრების საფუძველზე. მისმა მონასტრებმა და წესდებამ საერთო საცხოვრებლის მონაზვნობის განვითარებას შეუწყო ხელი.',array['Pachomius','Pakhomius','Pachomios','პახუმი დიდი']::text[],'saint','/icons/saints/pachomius-great.webp','https://www.oca.org/saints/lives/2026/05/15/101384-venerable-pachomius-the-great-founder-of-coenobitic-monasticism','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://www.oca.org/saints/lives/2026/05/15/101384-venerable-pachomius-the-great-founder-of-coenobitic-monasticism','Orthodox Church in America, Lives of the Saints: Saint Pachomius the Great; May 15.','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა პახუმი დიდი; 15 მაისი.','Saint Pachomius the Great — traditional Orthodox icon','წმინდა პახუმი დიდი — მართლმადიდებლური ხატი',true,133,'saints-expansion-2026:pachomius-great' where not exists(select 1 from public.authors where slug='pachomius-great' or legacy_key='saints-expansion-2026:pachomius-great' or lower(name_en)=lower('Saint Pachomius the Great')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'nino-georgia','Saint Nino, Enlightener of Georgia','پایەپیرۆز نینۆی ڕووناککەرەوەی جۆرجیا','წმინდა ნინო, საქართველოს განმანათლებელი','January 14','١٤ی کانوونی دووەم','14 იანვარი','Nino is venerated as Equal-to-the-Apostles for her missionary work in fourth-century Kartli, eastern Georgia.','نینۆ بەهۆی کاری مزگێنیدانی لە کارتلێی سەدەی چوارەم، لە ڕۆژهەڵاتی جۆرجیا، وەک هاوشانی نێردراوان ڕێزی لێ دەگیرێت.','ნინოს IV საუკუნის ქართლში სამოციქულო მოღვაწეობისთვის მოციქულთასწორად პატივს მიაგებენ.','Nino is venerated as Equal-to-the-Apostles for her missionary work in fourth-century Kartli, eastern Georgia. The Church remembers her role in the conversion of King Mirian and Queen Nana and in the establishment of Christianity in Georgia.','نینۆ بەهۆی کاری مزگێنیدانی لە کارتلێی سەدەی چوارەم، لە ڕۆژهەڵاتی جۆرجیا، وەک هاوشانی نێردراوان ڕێزی لێ دەگیرێت. کڵێسا ڕۆڵی لە مەسیحیبوونی پاشا میریان و شاژن نانا و دامەزراندنی مەسیحیەت لە جۆرجیا یاد دەکاتەوە.','ნინოს IV საუკუნის ქართლში სამოციქულო მოღვაწეობისთვის მოციქულთასწორად პატივს მიაგებენ. ეკლესია იხსენებს მის როლს მეფე მირიანისა და დედოფალ ნანას მოქცევასა და საქართველოში ქრისტიანობის დამკვიდრებაში.',array['Nino','Nina','Nino of Cappadocia','ნინო','საქართველოს განმანათლებელი']::text[],'saint','/icons/saints/nino-georgia.webp','https://www.oca.org/saints/lives/2026/01/14/100191-saint-nino-nina-equal-of-the-apostles-enlightener-of-georgia','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://www.oca.org/saints/lives/2026/01/14/100191-saint-nino-nina-equal-of-the-apostles-enlightener-of-georgia','Orthodox Church in America, Lives of the Saints: Saint Nino, Enlightener of Georgia; January 14.','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა ნინო, საქართველოს განმანათლებელი; 14 იანვარი.','Saint Nino, Enlightener of Georgia — traditional Orthodox icon','წმინდა ნინო, საქართველოს განმანათლებელი — მართლმადიდებლური ხატი',true,134,'saints-expansion-2026:nino-georgia' where not exists(select 1 from public.authors where slug='nino-georgia' or legacy_key='saints-expansion-2026:nino-georgia' or lower(name_en)=lower('Saint Nino, Enlightener of Georgia')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'shio-mgvime','Saint Shio of Mgvime','پایەپیرۆز شیۆی مەغڤیمە','წმინდა შიო მღვიმელი','May 9','٩ی ئایار','9 მაისი','Shio was one of the Syrian monastic fathers who came to Georgia in the sixth century.','شیۆ یەکێک بوو لە باوکە تاکمەندە سووریانییەکان کە لە سەدەی شەشەمدا هاتنە جۆرجیا.','შიო ერთ-ერთი იყო იმ ასურელ მამათაგან, რომლებიც VI საუკუნეში საქართველოში მოვიდნენ.','Shio was one of the Syrian monastic fathers who came to Georgia in the sixth century. He lived as an ascetic near Mtskheta, where the monastery known as Shio-Mgvime grew around his place of prayer.','شیۆ یەکێک بوو لە باوکە تاکمەندە سووریانییەکان کە لە سەدەی شەشەمدا هاتنە جۆرجیا. لە نزیک متسخێتا ژیانێکی زاهدانەی بەڕێ دەبرد، کە دواتر دێری ناسراو بە شیۆ-مەغڤیمە لە دەوری شوێنی نوێژەکەی گەشەی کرد.','შიო ერთ-ერთი იყო იმ ასურელ მამათაგან, რომლებიც VI საუკუნეში საქართველოში მოვიდნენ. იგი მცხეთის მახლობლად მოღვაწეობდა; მისი სალოცავი ადგილის გარშემო შემდგომ შიომღვიმის მონასტერი ჩამოყალიბდა.',array['Shio','Shio of Mgvime','Shio Mgvimeli','შიო მღვიმელი']::text[],'saint','/icons/saints/shio-mgvime.webp','https://www.oca.org/saints/lives/2026/05/09/101332-repose-of-venerable-shio-the-anchorite-of-georgia','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://www.oca.org/saints/lives/2026/05/09/101332-repose-of-venerable-shio-the-anchorite-of-georgia','Orthodox Church in America, Lives of the Saints: Saint Shio of Mgvime; May 9.','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა შიო მღვიმელი; 9 მაისი.','Saint Shio of Mgvime — traditional Orthodox icon','წმინდა შიო მღვიმელი — მართლმადიდებლური ხატი',true,135,'saints-expansion-2026:shio-mgvime' where not exists(select 1 from public.authors where slug='shio-mgvime' or legacy_key='saints-expansion-2026:shio-mgvime' or lower(name_en)=lower('Saint Shio of Mgvime')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'david-gareji','Saint David of Gareji','پایەپیرۆز داڤیدی گارێجی','წმინდა დავით გარეჯელი','Thursday after Ascension; also May 7 with the Thirteen Assyrian Fathers','پێنجشەممەی دوای بەرزبوونەوە؛ هەروەها ٧ی ئایار لەگەڵ سێزدە باوکە سووریانییەکان','ამაღლების შემდეგი ხუთშაბათი; აგრეთვე 7 მაისი — ცამეტ ასურელ მამასთან ერთად','David was a disciple of John of Zedazeni and one of the sixth-century monastic fathers who came to Georgia from Syria.','داڤید قوتابیی یۆحەنای زێدازێنی و یەکێک بوو لە باوکە تاکمەندەکانی سەدەی شەشەم کە لە سووریاوە هاتنە جۆرجیا.','დავითი იოანე ზედაზნელის მოწაფე და ერთ-ერთი იყო იმ ასურელ მამათაგან, რომლებიც VI საუკუნეში საქართველოში მოვიდნენ.','David was a disciple of John of Zedazeni and one of the sixth-century monastic fathers who came to Georgia from Syria. With his disciple Lucian, he established an ascetic community in the Gareji wilderness, which became an enduring centre of Georgian monastic life.','داڤید قوتابیی یۆحەنای زێدازێنی و یەکێک بوو لە باوکە تاکمەندەکانی سەدەی شەشەم کە لە سووریاوە هاتنە جۆرجیا. لەگەڵ قوتابییەکەی، لوکیان، کۆمەڵگەیەکی زاهدانەی لە چۆڵەوانیی گارێجی دامەزراند کە بوو بە ناوەندێکی بەردەوامی ژیانی تاکمەندیی جۆرجی.','დავითი იოანე ზედაზნელის მოწაფე და ერთ-ერთი იყო იმ ასურელ მამათაგან, რომლებიც VI საუკუნეში საქართველოში მოვიდნენ. თავის მოწაფე ლუკიანესთან ერთად მან გარეჯის უდაბნოში მონაზვნური თემი დააარსა, რომელიც ქართული სამონასტრო ცხოვრების მნიშვნელოვან ცენტრად იქცა.',array['David Gareji','David of Gareja','David Garejeli','დავით გარეჯელი']::text[],'saint','/icons/saints/david-gareji.webp','https://www.oca.org/saints/lives/2026/06/09/502-saint-david-gareji-and-venerable-lucian-spiritual-son-of-saint-d','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://patriarchate.ge/calendar/day/2026-05-28','Georgian Patriarchate, 2026 ecclesiastical calendar, May 28: Davidoba is movable, on the Thursday after Ascension. OCA, Saint David Gareji and Lucian: https://www.oca.org/saints/lives/2026/06/09/502-saint-david-gareji-and-venerable-lucian-spiritual-son-of-saint-d . May 7 collective commemoration: https://patriarchate.ge/calendar/day/2026-05-20 .','საქართველოს საპატრიარქოს 2026 წლის საეკლესიო კალენდარი, 28 მაისი: დავითობა გარდამავალია და ამაღლების შემდეგ ხუთშაბათს აღინიშნება. აგრეთვე 20 მაისი (7 მაისი ძველი სტილით) — ცამეტი ასურელი მამის საერთო ხსენება. ცხოვრება: ამერიკის მართლმადიდებელი ეკლესია, დავით გარეჯელი და ლუკიანე.','Saint David of Gareji — traditional Orthodox icon','წმინდა დავით გარეჯელი — მართლმადიდებლური ხატი',true,136,'saints-expansion-2026:david-gareji' where not exists(select 1 from public.authors where slug='david-gareji' or legacy_key='saints-expansion-2026:david-gareji' or lower(name_en)=lower('Saint David of Gareji')) on conflict do nothing;
insert into public.authors (slug,name_en,name_ckb,name_ka,feast_en,feast_ckb,feast_ka,summary_en,summary_ckb,summary_ka,biography_en,biography_ckb,biography_ka,aliases,kind,icon_url,icon_source,icon_credit,icon_credit_ka,source_url,source_reference,source_reference_ka,icon_alt,icon_alt_ka,published,sort_order,legacy_key) select 'euthymius-athonite','Saint Euthymius the Athonite','پایەپیرۆز ئەوتیمیۆسی ئاتۆس','წმინდა ექვთიმე ათონელი','May 13','١٣ی ئایار','13 მაისი','Euthymius was a Georgian monk and abbot associated with Iviron Monastery on Mount Athos.','ئەوتیمیۆس تاکمەند و سەرۆکدێرێکی جۆرجی بوو کە پەیوەندی بە دێری ئیڤیرۆن لە شاخی ئاتۆسەوە هەبوو.','ექვთიმე ქართველი ბერი და წინამძღვარი იყო, რომლის მოღვაწეობა ათონის ივერთა მონასტერს უკავშირდება.','Euthymius was a Georgian monk and abbot associated with Iviron Monastery on Mount Athos. His translations of Scripture and patristic works into Georgian made a lasting contribution to the Church''s theological and literary heritage.','ئەوتیمیۆس تاکمەند و سەرۆکدێرێکی جۆرجی بوو کە پەیوەندی بە دێری ئیڤیرۆن لە شاخی ئاتۆسەوە هەبوو. وەرگێڕانەکانی بۆ کتێبی پیرۆز و بەرهەمەکانی باوکانی کڵێسا بۆ زمانی جۆرجی بەشدارییەکی بەردەوامی لە میراتی باوەڕناسی و ئەدەبیی کڵێسا کرد.','ექვთიმე ქართველი ბერი და წინამძღვარი იყო, რომლის მოღვაწეობა ათონის ივერთა მონასტერს უკავშირდება. მისმა ქართულმა თარგმანებმა — წმინდა წერილმა და წმინდა მამათა ნაშრომებმა — ეკლესიის საღვთისმეტყველო და ლიტერატურულ მემკვიდრეობას მნიშვნელოვანი შენაძენი შესძინა.',array['Euthymius the Athonite','Euthymios of Iviron','Ekvtime Mtatsmindeli','ექვთიმე ათონელი','ექვთიმე მთაწმინდელი']::text[],'saint','/icons/saints/euthymius-athonite.webp','https://www.oca.org/saints/lives/2026/05/13/101371-saint-euthymius-the-new-founder-of-the-ivron-monastery-and-his-f','Traditional Orthodox icon published by the Orthodox Church in America. Copyright and image rights remain with the source.','ტრადიციული მართლმადიდებლური ხატი გამოქვეყნებულია ამერიკის მართლმადიდებელი ეკლესიის ვებგვერდზე. საავტორო უფლებები ეკუთვნის წყაროს.','https://www.oca.org/saints/lives/2026/05/13/101371-saint-euthymius-the-new-founder-of-the-ivron-monastery-and-his-f','Orthodox Church in America, Lives of the Saints: Saint Euthymius the Athonite; May 13.','ამერიკის მართლმადიდებელი ეკლესია, წმინდანთა ცხოვრება: წმინდა ექვთიმე ათონელი; 13 მაისი.','Saint Euthymius the Athonite — traditional Orthodox icon','წმინდა ექვთიმე ათონელი — მართლმადიდებლური ხატი',true,137,'saints-expansion-2026:euthymius-athonite' where not exists(select 1 from public.authors where slug='euthymius-athonite' or legacy_key='saints-expansion-2026:euthymius-athonite' or lower(name_en)=lower('Saint Euthymius the Athonite')) on conflict do nothing;
commit;
